const fs = require('fs');
const path = require('path');
const projectPath = (...parts) => path.join(__dirname, ...parts);
const reportedProjectReadErrors = new Set();
const projectAssetCache = new Map();
function readProjectJson(filePath, fallback) {
    const file = path.isAbsolute(String(filePath))
        ? String(filePath)
        : projectPath(String(filePath).replace(/^\.?[\/]+/, ''));
    try {
        const parsed = JSON.parse(fs.readFileSync(file, 'utf8'));
        return parsed === undefined || parsed === null ? fallback : parsed;
    } catch (error) {
        const key = `${file}:${error?.code || error?.name || 'read-error'}`;
        if (!reportedProjectReadErrors.has(key)) {
            reportedProjectReadErrors.add(key);
            if (error?.code !== 'ENOENT') console.error(`[PROJECT JSON READ] ${file}: ${error?.message || error}`);
        }
        return fallback;
    }
}
function readProjectAsset(filePath) {
    const file = path.isAbsolute(String(filePath)) ? String(filePath) : projectPath(String(filePath).replace(/^\.?[\/]+/, ''));
    if (projectAssetCache.has(file)) return projectAssetCache.get(file);
    try {
        const buffer = fs.readFileSync(file);
        projectAssetCache.set(file, buffer);
        return buffer;
    } catch (error) {
        const key = `${file}:${error?.code || error?.name || 'read-error'}`;
        if (!reportedProjectReadErrors.has(key)) {
            reportedProjectReadErrors.add(key);
            console.error(`[PROJECT ASSET READ] ${file}: ${error?.message || error}`);
        }
        return Buffer.alloc(0);
    }
}
