// TikTok format choices are kept in memory for a few minutes. The opaque token
// prevents very long URLs in WhatsApp button IDs and binds each choice to the
// chat/sender that requested it.
const TIKTOK_DOWNLOAD_SELECTIONS = new Map();
const TIKTOK_DOWNLOAD_SELECTION_TTL = 5 * 60 * 1000;
const TIKTOK_DOWNLOAD_SELECTION_MAX = 250;
function pruneTikTokDownloadSelections(now = Date.now()) {
    for (const [token, selection] of TIKTOK_DOWNLOAD_SELECTIONS) {
        if (!selection || Number(selection.expiresAt || 0) <= now) {
            TIKTOK_DOWNLOAD_SELECTIONS.delete(token);
        }
    }
}
function createTikTokDownloadSelection({ sender, chat, url, result }) {
    const now = Date.now();
    pruneTikTokDownloadSelections(now);
    while (TIKTOK_DOWNLOAD_SELECTIONS.size >= TIKTOK_DOWNLOAD_SELECTION_MAX) {
        const oldestToken = TIKTOK_DOWNLOAD_SELECTIONS.keys().next().value;
        if (!oldestToken) break;
        TIKTOK_DOWNLOAD_SELECTIONS.delete(oldestToken);
    }
    let token;
    do { token = crypto.randomBytes(6).toString('hex'); }
    while (TIKTOK_DOWNLOAD_SELECTIONS.has(token));
    TIKTOK_DOWNLOAD_SELECTIONS.set(token, {
        sender: String(sender || ''),
        chat: String(chat || ''),
        url: String(url || ''),
        result,
        createdAt: now,
        expiresAt: now + TIKTOK_DOWNLOAD_SELECTION_TTL,
        processing: false
    });
    return token;
}
function getTikTokDownloadSelection(token, sender, chat) {
    const key = String(token || '').trim();
    pruneTikTokDownloadSelections();
    const selection = TIKTOK_DOWNLOAD_SELECTIONS.get(key);
    if (!selection) return { error: 'Pilihan download TikTok sudah kedaluwarsa. Kirim ulang perintah TikTok dengan link yang sama.' };
    if (selection.sender !== String(sender || '') || selection.chat !== String(chat || '')) {
        return { error: 'Tombol ini dibuat oleh pengguna/chat lain. Kirim link TikTok sendiri untuk membuat pilihan baru.', unauthorized: true };
    }
    return { selection, token: key };
}
