// conn.getName dapat mengembalikan string biasa (terutama JID pengguna pribadi),
// atau Promise untuk beberapa tipe JID. Jangan akses .catch langsung pada hasilnya.
async function getXeryuuContactNameSafe(conn, jid, fallback = '') {
    const rawJid = String(jid || '').trim()
    const jidName = rawJid.includes('@') ? rawJid.split('@')[0].split(':')[0] : rawJid
    const fallbackName = String(fallback || '').trim() || jidName || 'Pengguna'
    if (!rawJid) return fallbackName

    try {
        if (typeof conn?.getName === 'function') {
            const result = await conn.getName(rawJid)
            const displayName = String(result ?? '').replace(/[\r\n\t]/g, ' ').replace(/\s+/g, ' ').trim()
            if (displayName) return displayName
        }
    } catch (error) {
        // Kontak/LID yang tidak ada di store tetap ditangani memakai fallback JID.
    }
    return fallbackName
}

