async function startAnonymous(conn, jid) {
    if (anonymousSessions.has(jid)) {
        return conn.sendMessage(jid, {
            text: `\`\`\`❌ Kamu masih terhubung dengan pasangan anonymous.\n\nGunakan .anon stop terlebih dahulu.\`\`\``
        })
    }

    if (anonymousQueue.includes(jid)) {
        return conn.sendMessage(jid, {
            text: `\`\`\`⏳ Kamu masih menunggu pasangan anonymous.\`\`\``
        })
    }

    if (anonymousQueue.length > 0) {
        const partner = anonymousQueue.shift()

        anonymousSessions.set(jid, partner)
        anonymousSessions.set(partner, jid)

        await conn.sendMessage(jid, {
            text: `\`\`\`🟢 Anonymous Chat Terhubung!*\n\nSilakan mulai mengobrol.\n\nKetik .anon stop untuk keluar.\`\`\``
        })

        await conn.sendMessage(partner, {
            text: '🟢 Anonymous Chat Terhubung!\n\nSilakan mulai mengobrol.\n\nKetik .anon stop untuk keluar.'
        })
        return
    }
    anonymousQueue.push(jid)
    return conn.sendMessage(jid, {
        text: `\`\`\`🔎 Mencari pasangan anonymous...\n\nKamu masuk antrean. Tunggu pengguna lain.\`\`\``
    })
}

async function stopAnonymous(conn, jid) {
    if (anonymousQueue.includes(jid)) {
        removeFromAnonymousQueue(jid)

        return conn.sendMessage(jid, {
            text: `\`\`\`🔴 Kamu keluar dari antrean anonymous.\`\`\``
        })
    }

    const partner = anonymousSessions.get(jid)

    if (!partner) {
        return conn.sendMessage(jid, {
            text: `\`\`\`❌ Kamu tidak sedang berada di anonymous chat.\`\`\``
        })
    }
    anonymousSessions.delete(jid)
    anonymousSessions.delete(partner)
    await conn.sendMessage(jid, {
        text: `\`\`\`🔴 Anonymous Chat dihentikan.\`\`\``
    })
    await conn.sendMessage(partner, {
        text: `\`\`\`🔴 Pasangan anonymous keluar dari chat\`\`\``
    })
} 

// Semua command masuk ke satu antrean FIFO agar proses berat (play, HD, menu,
// dan command lain) tidak berjalan tumpang-tindih dan membanjiri WhatsApp.
const xeryuuCommandQueue = []
const xeryuuQueueNoticeAt = new Map()
let xeryuuCommandQueueRunning = false
let xeryuuQueueLastCleanupAt = 0
const XERYUU_MAX_PENDING_COMMANDS = 60
const XERYUU_QUEUE_NOTICE_INTERVAL_MS = 3000

const XERYUU_BROADCAST_QUEUE_BYPASS_COMMANDS = new Set([
    'broadcast', 'bc', 'stopbroadcast', 'broadcaststop', 'stopbc', 'broadcaststatus', 'bcstatus'
])
if (!global.__xeryuuBroadcastState || typeof global.__xeryuuBroadcastState !== 'object') {
    global.__xeryuuBroadcastState = {
        active: false,
        stopRequested: false,
        status: 'idle',
        startedAt: 0,
        finishedAt: 0,
        targetCount: 0,
        processed: 0,
        sent: 0,
        failed: 0,
        skippedBlacklist: 0,
        limit: null,
        currentJid: '',
        startChat: '',
        lastError: ''
    }
}

function isXeryuuBroadcastSocketReady(socket) {
    if (!socket || typeof socket.sendMessage !== 'function') return false
    if (socket.isConnected === false) return false
    const readyState = socket.ws?.readyState
    if (typeof readyState === 'number' && readyState !== 1) return false
    return socket.isConnected === true || readyState === 1 || typeof socket.isConnected === 'undefined'
}

function isXeryuuBroadcastConnectionError(error) {
    const message = String(error?.message || error || '')
    return /connection\s*closed|connection\s+is\s+closed|websocket[^\n]*closed|socket[^\n]*closed|not connected|connection lost|timed?\s*out/i.test(message)
}

async function waitForXeryuuBroadcastSocket(fallbackSocket, state, options = {}) {
    const timeoutMs = Math.max(10000, Number(options.timeoutMs) || 10 * 60 * 1000)
    const excludeSocket = options.excludeSocket || null
    const startedAt = Date.now()
    let loggedWaiting = false

    while (Date.now() - startedAt < timeoutMs) {
        if (state?.stopRequested) return { socket: null, stopped: true, timedOut: false }
        const currentSocket = global.__xeryuuMainSocket || fallbackSocket || null
        if (currentSocket !== excludeSocket && isXeryuuBroadcastSocketReady(currentSocket)) {
            return { socket: currentSocket, stopped: false, timedOut: false }
        }
        if (!loggedWaiting) {
            loggedWaiting = true
            console.warn('Koneksi WhatsApp belum siap; menunggu reconnect dan broadcast akan dilanjutkan otomatis.')
        }
        if (state) state.status = 'waiting-connection'
        await new Promise(resolve => setTimeout(resolve, 1000))
    }
    return { socket: null, stopped: Boolean(state?.stopRequested), timedOut: true }
}

async function fetchXeryuuBroadcastGroups(fallbackSocket, state) {
    let previousSocket = null
    let reconnectRetries = 0
    while (!state?.stopRequested) {
        const ready = await waitForXeryuuBroadcastSocket(fallbackSocket, state, {
            excludeSocket: previousSocket,
            timeoutMs: 10 * 60 * 1000
        })
        if (ready.stopped) return null
        if (!ready.socket) {
            throw new Error('Koneksi WhatsApp tidak pulih dalam 10 menit saat menyiapkan daftar grup.')
        }
        try {
            return await ready.socket.groupFetchAllParticipating()
        } catch (error) {
            if (!isXeryuuBroadcastConnectionError(error) || reconnectRetries >= 3) throw error
            reconnectRetries++
            previousSocket = ready.socket
            state.status = 'waiting-connection'
            console.warn(`Gagal mengambil daftar grup karena koneksi terputus; menunggu reconnect (${reconnectRetries}/3).`)
        }
    }
    return null
}

async function drainXeryuuCommandQueue() {
    if (xeryuuCommandQueueRunning) return
    xeryuuCommandQueueRunning = true
    try {
        while (xeryuuCommandQueue.length > 0) {
            const entry = xeryuuCommandQueue.shift()
            try {
                entry.resolve(await entry.task())
            } catch (error) {
                entry.reject(error)
            }
        }
    } finally {
        xeryuuCommandQueueRunning = false
        if (xeryuuCommandQueue.length > 0) void drainXeryuuCommandQueue()
    }
}

async function addCommandToQueue(task, meta = {}) {
   
    const commandName = String(meta.commandName || '').toLowerCase().trim()
    if (XERYUU_BROADCAST_QUEUE_BYPASS_COMMANDS.has(commandName)) return await task()

    // Pesan biasa dan input jawaban game yang bukan command tetap diproses langsung.
    if (meta.isCommand !== true) return await task()

    const conn = meta.conn
    const message = meta.message
    const chat = String(meta.chat || message?.chat || '')
    const sender = String(meta.sender || message?.sender || '')
    if (!conn || !chat || !sender) return await task()

    const now = Date.now()
    if (now - xeryuuQueueLastCleanupAt > 60000 || xeryuuQueueNoticeAt.size > 3000) {
        xeryuuQueueLastCleanupAt = now
        for (const [noticeKey, sentAt] of xeryuuQueueNoticeAt) {
            if (now - sentAt > 60000) xeryuuQueueNoticeAt.delete(noticeKey)
        }
    }

    if (xeryuuCommandQueue.length >= XERYUU_MAX_PENDING_COMMANDS) {
        try {
            await conn.sendMessage(chat, {
                text: '⚠️ *ANTREAN COMMAND PENUH*\n\nCommand belum dimasukkan ke antrean karena terlalu banyak proses yang sedang menunggu. Coba kirim kembali setelah antrean berkurang ya.'
            }, message?.key && message?.message ? { quoted: message } : undefined)
        } catch (error) {
            console.warn('[COMMAND QUEUE FULL NOTICE]', error?.message || error)
        }
        return
    }

    const wasBusy = xeryuuCommandQueueRunning || xeryuuCommandQueue.length > 0
    const result = new Promise((resolve, reject) => {
        xeryuuCommandQueue.push({ task, resolve, reject, chat, sender })
    })

    if (wasBusy) {
        const noticeKey = `${chat}::${sender}`
        const lastNoticeAt = Number(xeryuuQueueNoticeAt.get(noticeKey) || 0)
        if (now - lastNoticeAt >= XERYUU_QUEUE_NOTICE_INTERVAL_MS) {
            xeryuuQueueNoticeAt.set(noticeKey, now)
            const position = xeryuuCommandQueue.length + (xeryuuCommandQueueRunning ? 1 : 0)
            try {
                await conn.sendMessage(chat, {
                    text: `⏳ *XERYUU COMMAND QUEUE*\n\nTunggu antrian dulu ya agar bot tidak terkena spam oleh WhatsApp.\n\n📍 Posisi antrean: *${position}*\n✅ Command kamu sudah masuk antrean dan akan diproses otomatis setelah giliran sebelumnya selesai.\n\nMohon jangan kirim command yang sama berulang kali.`
                }, message?.key && message?.message ? { quoted: message } : undefined)
            } catch (error) {
                console.warn('[COMMAND QUEUE NOTICE]', error?.message || error)
            }
        }
    } else {
        void drainXeryuuCommandQueue()
    }

    return await result
}

