async function getGroupMetadata(conn, jid, fallback = null) {
    if (!jid) return null
    const cache = conn.__xeryuuGroupMetadataCache
    const cached = cache.get(jid)
    if (fallback?.participants && fallback?.id === jid) {
        cache.set(jid, { data: fallback, time: Date.now() })
        return fallback
    }

    if (cached && Date.now() - cached.time < 60000) {
        return cached.data
    }

    try {
        const data = await Promise.race([
            conn.groupMetadata(jid),
            new Promise((_, reject) =>
                setTimeout(() => reject(new Error('groupMetadata timeout')), 8000)
            )
        ])

        cache.set(jid, {
            data: data,
            time: Date.now()
        })

        return data
    } catch (e) {
        if (e?.data === 429 || e?.message?.includes('rate-overlimit')) {
            console.log(`⚠️ Rate limit groupMetadata: ${jid}`)
            return cached?.data || fallback || null
        }

        if (e?.message === 'groupMetadata timeout') {
            console.log(`⚠️ Timeout groupMetadata: ${jid}`)
            return cached?.data || fallback || null
        }

        console.error(`[GROUP METADATA ERROR] ${jid}:`, e?.message || e)
        return cached?.data || fallback || null
    }
}
