async function updateGroupActivity(conn, m, groupMetadata) {
    try {
        if (!m?.isGroup || !m?.sender || !groupMetadata) return
        if (m.key?.fromMe) return
        if (!global.db?.groups?.[m.chat]) return

        const groupDb = global.db.groups[m.chat]

        if (!groupDb.inactive) {
            groupDb.inactive = {}
        }

        const participant = groupMetadata.participants?.find(p => participantMatchesMessage(p, m))

        if (!participant) return

        // Admin tidak dihitung sebagai inactive
        if (participant.admin) return

        const jid =
            participant.id ||
            participant.phoneNumber ||
            participant.lid ||
            m.sender
        groupDb.inactive[jid] = {
            lastActive: Date.now(),
            messages:
                (groupDb.inactive[jid]?.messages || 0) + 1
        }
    } catch (err) {
        console.error('[INACTIVE TRACK ERROR]', err)
    }
}
