const statsFolder = path.join(__dirname, './db')
const statsFile = path.join(statsFolder, 'groupStats.json')
if (!fs.existsSync(statsFolder)) fs.mkdirSync(statsFolder)
if (!fs.existsSync(statsFile)) fs.writeFileSync(statsFile, '{}')
function loadStats() {
  const data = readProjectJson(statsFile, {})
  return data && typeof data === 'object' && !Array.isArray(data) ? data : {}
}
function saveStats(data) {
  fs.writeFileSync(statsFile, JSON.stringify(data, null, 2))
}
function updateStats(groupId, senderId) {
  const data = loadStats()
  const today = new Date().toISOString().slice(0, 10)
  if (!data[groupId]) data[groupId] = {}
  if (!data[groupId][today]) data[groupId][today] = {}
  if (!data[groupId][today][senderId]) data[groupId][today][senderId] = 0
  data[groupId][today][senderId]++
  saveStats(data)
}
function getTodayStats(groupId) {
  const data = loadStats()
  const today = new Date().toISOString().slice(0, 10)
  return data[groupId]?.[today] || {}
}

const userChatStatsFile = path.join(statsFolder, 'userChatStats.json')
if (!fs.existsSync(userChatStatsFile)) fs.writeFileSync(userChatStatsFile, '{}')
function loadUserChatStats() {
  const data = readProjectJson(userChatStatsFile, {})
  return data && typeof data === 'object' && !Array.isArray(data) ? data : {}
}
function updateUserChatStats(chat, senderId, isGroupChat) {
  if (!senderId) return
  try {
    const data = loadUserChatStats()
    const entry = data[senderId] && typeof data[senderId] === 'object'
      ? data[senderId]
      : { totalChats: 0, totalGroupChats: 0, totalPrivateChats: 0, groups: {} }
    entry.totalChats = Math.max(0, Number(entry.totalChats) || 0) + 1
    if (isGroupChat) {
      entry.totalGroupChats = Math.max(0, Number(entry.totalGroupChats) || 0) + 1
      if (!entry.groups || typeof entry.groups !== 'object' || Array.isArray(entry.groups)) entry.groups = {}
      entry.groups[chat] = true
    } else {
      entry.totalPrivateChats = Math.max(0, Number(entry.totalPrivateChats) || 0) + 1
    }
    entry.lastMessageAt = Date.now()
    data[senderId] = entry
    fs.writeFileSync(userChatStatsFile, JSON.stringify(data, null, 2))
  } catch (error) {
    console.error('[USER CHAT STATS]', error?.message || error)
  }
}

