// Native list menus keep long product catalogues readable and selectable.
const sendWaListMenu = async ({
    text,
    title = 'Pilih layanan',
    footer = 'Xeryuu-Md V16 × Sendrich • Store',
    sections = [],
    fallbackText = '',
    artworkKey = '',
    imageBuffer = null
}) => {
    const safeSections = []
    let remainingRows = 10

    for (const section of sections) {
        if (remainingRows <= 0) break
        const rows = (Array.isArray(section?.rows) ? section.rows : [])
            .slice(0, remainingRows)
            .map(row => ({
                title: String(row.title || 'Pilihan').replace(/[\r\n]/g, ' ').slice(0, 24),
                description: String(row.description || '').replace(/[\r\n]/g, ' ').slice(0, 72),
                id: String(row.id || `${prefix}store`).slice(0, 256)
            }))
        if (!rows.length) continue
        safeSections.push({
            title: String(section.title || 'Pilihan tersedia').replace(/[\r\n]/g, ' ').slice(0, 24),
            rows
        })
        remainingRows -= rows.length
    }

    const plainFallback = fallbackText || `${text || ''}\n\nJika daftar pilihan tidak muncul, ketik perintah yang tertera pada menu.`
    if (!safeSections.length) {
        return sendXeryuuImageReply(plainFallback)
    }

    let artworkMedia = {}
    const artworkName = String(artworkKey || '').toLowerCase()
    const directArtwork = Buffer.isBuffer(imageBuffer) && imageBuffer.length
        ? imageBuffer
        : (artworkName && STORE_ARTWORK_FILES[artworkName]
            ? readProjectAsset(STORE_ARTWORK_FILES[artworkName])
            : readProjectAsset('media/xeryuu.png'))
    if (Buffer.isBuffer(directArtwork) && directArtwork.length) {
        try {
            artworkMedia = await prepareWAMessageMedia(
                { image: directArtwork },
                { upload: conn.waUploadToServer }
            )
        } catch (mediaError) {
            console.error(`[STORE ARTWORK PREPARE:${artworkName || 'custom'}]`, mediaError?.message || mediaError)
            artworkMedia = {}
        }
    }

    try {
        const waMessage = generateWAMessageFromContent(m.chat, {
            viewOnceMessage: {
                message: {
                    messageContextInfo: {
                        deviceListMetadata: {},
                        deviceListMetadataVersion: 2
                    },
                    interactiveMessage: proto.Message.InteractiveMessage.fromObject({
                        header: proto.Message.InteractiveMessage.Header.fromObject({
                            title: String(title || 'Pilih layanan').slice(0, 60),
                            hasMediaAttachment: Boolean(artworkMedia?.imageMessage),
                            ...artworkMedia
                        }),
                        body: proto.Message.InteractiveMessage.Body.fromObject({ text: String(text || '') }),
                        footer: proto.Message.InteractiveMessage.Footer.fromObject({ text: String(footer || '') }),
                        nativeFlowMessage: proto.Message.InteractiveMessage.NativeFlowMessage.fromObject({
                            buttons: [{
                                name: 'single_select',
                                buttonParamsJson: JSON.stringify({
                                    title: String(title || 'Pilih layanan').slice(0, 20),
                                    sections: safeSections
                                })
                            }],
                            messageParamsJson: '{}'
                        })
                    })
                }
            }
        }, { quoted: m, userJid: m.sender })

        await conn.relayMessage(m.chat, waMessage.message, { messageId: waMessage.key.id })
        return waMessage
    } catch (error) {
        console.error('[WHATSAPP STORE LIST]', error?.stack || error)
        return sendXeryuuImageReply(plainFallback)
    }
}

