// Cache daftar grup agar navigasi blacklist tidak memanggil endpoint grup berulang.
// Saat WhatsApp mengembalikan rate-overlimit, gunakan cache terakhir; jangan gagal total.
const BROADCAST_GROUP_CACHE_TTL_MS = 5 * 60 * 1000
let broadcastGroupCache = null
let broadcastGroupCacheAt = 0
let broadcastGroupFetchPromise = null
let broadcastGroupRetryAt = 0
const getBroadcastGroups = async ({ force = false } = {}) => {
    const now = Date.now()
    if (!force && broadcastGroupCache && now - broadcastGroupCacheAt < BROADCAST_GROUP_CACHE_TTL_MS) return broadcastGroupCache
    if (!force && now < broadcastGroupRetryAt && broadcastGroupCache) return broadcastGroupCache
    if (broadcastGroupFetchPromise) return broadcastGroupFetchPromise
    broadcastGroupFetchPromise = (async () => {
        try {
            const fetched = await conn.groupFetchAllParticipating()
            if (!fetched || typeof fetched !== 'object') throw new Error('Respons daftar grup tidak valid')
            broadcastGroupCache = fetched
            broadcastGroupCacheAt = Date.now()
            broadcastGroupRetryAt = 0
            return fetched
        } catch (error) {
            const message = String(error?.message || error)
            if (/rate-overlimit|rate[ -]?limit|too many requests|\b429\b/i.test(message) || error?.data === 429) {
                broadcastGroupRetryAt = Date.now() + 60 * 1000
                console.warn('[BROADCAST BLACKLIST] WhatsApp rate-limit; memakai cache grup yang tersedia.')
            }
            if (broadcastGroupCache) return broadcastGroupCache
            throw error
        } finally {
            broadcastGroupFetchPromise = null
        }
    })()
    return broadcastGroupFetchPromise
}

const sendBlacklistBroadcastMenu = async (requestedPage = 1, notice = '') => {
    const groupObject = await getBroadcastGroups()
    const groups = Object.entries(groupObject || {})
        .map(([jid, meta]) => ({
            jid,
            subject: String(meta?.subject || meta?.name || 'Grup tanpa nama').replace(/[\r\n]+/g, ' ').trim()
        }))
        .sort((a, b) => a.subject.localeCompare(b.subject, 'id'))

    if (!groups.length) return sendXeryuuImageReply('❌ Bot belum tergabung di grup mana pun.')
    if (!global.db.groups || typeof global.db.groups !== 'object') global.db.groups = {}

    const isBlocked = (jid) => Boolean(global.db.groups?.[jid]?.blacklistjpm || global.db.chats?.[jid]?.blacklistjpm)
    const blockedCount = groups.filter(({ jid }) => isBlocked(jid)).length
    const pageSize = 7
    const totalPages = Math.max(1, Math.ceil(groups.length / pageSize))
    const parsedPage = Number.parseInt(String(requestedPage ?? '1'), 10) || 1
    const page = Math.max(1, Math.min(totalPages, parsedPage))
    const pageGroups = groups.slice((page - 1) * pageSize, page * pageSize)

    const rows = pageGroups.map(group => {
        const blocked = isBlocked(group.jid)
        return {
            title: `${blocked ? '🚫' : '🟢'} ${group.subject}`.slice(0, 24),
            description: blocked
                ? 'Blacklist aktif • tap untuk izinkan broadcast'
                : 'Broadcast aktif • tap untuk blacklist',
            id: `${prefix}broadcastblacklisttoggle ${page} ${group.jid}`
        }
    })
    if (page > 1) rows.push({
        title: '⬅️ Halaman sebelumnya',
        description: `Kembali ke halaman ${page - 1}`,
        id: `${prefix}blacklistbroadcast ${page - 1}`
    })
    if (page < totalPages) rows.push({
        title: '➡️ Halaman berikutnya',
        description: `Lihat halaman ${page + 1} dari ${totalPages}`,
        id: `${prefix}blacklistbroadcast ${page + 1}`
    })
    rows.push({
        title: '🔄 Muat ulang daftar',
        description: 'Perbarui status blacklist grup',
        id: `${prefix}blacklistbroadcast ${page}`
    })

    const heading = '📣 BLACKLIST BROADCAST GRUP'
    const detail =
        `${heading}\n\n` +
        `${notice ? `${notice}\n\n` : ''}` +
        `Pilih grup dari tombol *Kelola blacklist* untuk mengubah status.\n` +
        `🟢 = boleh menerima broadcast\n` +
        `🚫 = masuk blacklist dan dilewati saat broadcast\n\n` +
        `📄 Halaman: ${page}/${totalPages}\n` +
        `👥 Total grup: ${groups.length}\n` +
        `🚫 Grup blacklist: ${blockedCount}\n\n` +
        `Perubahan disimpan ke database bot.`

    // Text fallback is only used if WhatsApp rejects the native list; the normal
    // path sends one selectable menu button, with up to 7 groups and page controls.
    const manualRows = pageGroups.map(group =>
        `• ${isBlocked(group.jid) ? '🚫' : '🟢'} ${group.subject}\n  ${prefix}broadcastblacklisttoggle ${page} ${group.jid}`
    ).join('\n')
    const fallbackText =
        `${detail}\n\nDaftar manual halaman ${page}:\n${manualRows}\n\n` +
        (page > 1 ? `Halaman sebelumnya: ${prefix}blacklistbroadcast ${page - 1}\n` : '') +
        (page < totalPages ? `Halaman berikutnya: ${prefix}blacklistbroadcast ${page + 1}` : '')

    return sendWaListMenu({
        text: detail,
        title: 'Kelola blacklist',
        footer: 'Xeryuu-MD V16 • Blacklist Broadcast',
        sections: [{ title: `Grup • halaman ${page}/${totalPages}`.slice(0, 24), rows }],
        imageBuffer: readProjectAsset('media/xeryuu.png'),
        fallbackText
    })
}

// Daftar grup Auto Adzan memakai cache bersama dengan scheduler agar navigasi
// halaman/tombol tidak memanggil groupFetchAllParticipating berulang kali.
const ADZAN_GROUP_CACHE_TTL_MS = 5 * 60 * 1000
let adzanGroupObjectCache = null
let adzanGroupObjectCacheAt = 0
let adzanGroupObjectCacheSource = ''
let adzanGroupFetchPromise = null
let adzanGroupFetchRetryAt = 0
let adzanGroupLastFetchError = ''

const sanitizeAdzanGroupObject = value => Object.fromEntries(
    Object.entries(value && typeof value === 'object' ? value : {})
        .filter(([jid]) => String(jid).endsWith('@g.us'))
)

const getAdzanFilterGroupObject = async () => {
    const now = Date.now()
    const sharedCache = global.__xeryuuParticipatingGroupsCache
    const sharedData = sharedCache?.data
    const sharedFetchedAt = Number(sharedCache?.fetchedAt) || 0

    // Scheduler Auto Adzan sudah mengambil daftar maksimal setiap 5 menit.
    // Gunakan hasil itu alih-alih meminta daftar grup lagi dari WhatsApp.
    if (sharedData && typeof sharedData === 'object' && sharedFetchedAt > 0 &&
        now - sharedFetchedAt < ADZAN_GROUP_CACHE_TTL_MS) {
        const sanitized = sanitizeAdzanGroupObject(sharedData)
        adzanGroupObjectCache = sanitized
        adzanGroupObjectCacheAt = sharedFetchedAt
        adzanGroupObjectCacheSource = 'shared-cache'
        return { groupObject: sanitized, source: 'shared-cache' }
    }

    if (adzanGroupObjectCache !== null && now - adzanGroupObjectCacheAt < ADZAN_GROUP_CACHE_TTL_MS) {
        return { groupObject: adzanGroupObjectCache, source: adzanGroupObjectCacheSource || 'cache' }
    }
    if (adzanGroupFetchPromise) return adzanGroupFetchPromise
    if (now < adzanGroupFetchRetryAt) {
        throw new Error(adzanGroupLastFetchError || 'WhatsApp sedang membatasi permintaan daftar grup. Coba kembali setelah sekitar 1 menit.')
    }

    adzanGroupFetchPromise = (async () => {
        try {
            if (!conn || typeof conn.groupFetchAllParticipating !== 'function') {
                throw new Error('Koneksi WhatsApp belum siap untuk memuat daftar grup.')
            }
            const fetched = await conn.groupFetchAllParticipating()
            if (!fetched || typeof fetched !== 'object') {
                throw new Error('WhatsApp mengembalikan daftar grup dengan format tidak valid.')
            }
            const sanitized = sanitizeAdzanGroupObject(fetched)
            const fetchedAt = Date.now()
            adzanGroupObjectCache = sanitized
            adzanGroupObjectCacheAt = fetchedAt
            adzanGroupObjectCacheSource = 'live'
            adzanGroupFetchRetryAt = 0
            adzanGroupLastFetchError = ''
            global.__xeryuuParticipatingGroupsCache = { data: sanitized, fetchedAt }
            return { groupObject: sanitized, source: 'live' }
        } catch (error) {
            const errorText = String(error?.message || error || '')
            const rateLimited = /rate-overlimit|rate[ -]?limit|too many requests|\b429\b/i.test(errorText)

            // Saat WhatsApp membatasi permintaan, gunakan cache terakhir yang
            // pernah berhasil sebelum beralih ke daftar lokal database.
            if (adzanGroupObjectCache !== null && Object.keys(adzanGroupObjectCache).length) {
                adzanGroupObjectCacheAt = Date.now()
                adzanGroupObjectCacheSource = 'stale-cache'
                return { groupObject: adzanGroupObjectCache, source: 'stale-cache' }
            }
            if (sharedData && typeof sharedData === 'object' && Object.keys(sharedData).length) {
                const sanitized = sanitizeAdzanGroupObject(sharedData)
                adzanGroupObjectCache = sanitized
                adzanGroupObjectCacheAt = Date.now()
                adzanGroupObjectCacheSource = 'stale-cache'
                return { groupObject: sanitized, source: 'stale-cache' }
            }

            const localGroups = {}
            for (const [jid, group] of Object.entries(global.db?.groups || {})) {
                if (!String(jid).endsWith('@g.us')) continue
                const chat = global.db?.chats?.[jid]
                const fallbackName = group?.name || group?.subject || chat?.name || chat?.subject
                localGroups[jid] = {
                    subject: String(fallbackName || `Grup ${String(jid).split('@')[0].slice(-8)}`)
                }
            }
            if (Object.keys(localGroups).length) {
                adzanGroupObjectCache = localGroups
                adzanGroupObjectCacheAt = Date.now()
                adzanGroupObjectCacheSource = 'database'
                return { groupObject: localGroups, source: 'database' }
            }

            if (rateLimited) {
                adzanGroupFetchRetryAt = Date.now() + 60_000
                adzanGroupLastFetchError = 'WhatsApp sedang membatasi permintaan daftar grup (rate-overlimit), dan cache/database grup belum tersedia. Coba kembali setelah sekitar 1 menit.'
                throw new Error(adzanGroupLastFetchError)
            }
            throw error
        } finally {
            adzanGroupFetchPromise = null
        }
    })()
    return adzanGroupFetchPromise
}

// Filter notifikasi Auto Adzan uses the same paginated native list pattern as
// blacklist broadcast. Excluded groups receive neither the adzan audio/text nor
// the automatic group-closing action at prayer time.
const sendAdzanBlacklistMenu = async (requestedPage = 1, notice = '') => {
    const groupResult = await getAdzanFilterGroupObject()
    const groupObject = groupResult.groupObject
    const cacheNotice = groupResult.source === 'database'
        ? '⚠️ WhatsApp sedang membatasi permintaan. Daftar sementara diambil dari database lokal; grup yang baru ditambahkan mungkin belum muncul.'
        : groupResult.source === 'stale-cache'
            ? '⚠️ WhatsApp sedang membatasi permintaan. Daftar memakai cache grup terakhir yang berhasil dimuat.'
            : ''
    const displayNotice = [notice, cacheNotice].filter(Boolean).join('\n')
    const groups = Object.entries(groupObject || {})
        .map(([jid, meta]) => ({
            jid,
            subject: String(meta?.subject || meta?.name || 'Grup tanpa nama').replace(/[\r\n]+/g, ' ').trim()
        }))
        .filter(group => group.jid.endsWith('@g.us'))
        .sort((a, b) => a.subject.localeCompare(b.subject, 'id'))

    if (!groups.length) return sendXeryuuImageReply('❌ Bot belum tergabung di grup mana pun.')
    if (!global.db.groups || typeof global.db.groups !== 'object') global.db.groups = {}

    const isBlocked = jid => global.db.groups?.[jid]?.blacklistadzan === true || global.db.chats?.[jid]?.blacklistadzan === true
    const blockedCount = groups.filter(({ jid }) => isBlocked(jid)).length
    const pageSize = 7
    const totalPages = Math.max(1, Math.ceil(groups.length / pageSize))
    const parsedPage = Number.parseInt(String(requestedPage ?? '1'), 10) || 1
    const page = Math.max(1, Math.min(totalPages, parsedPage))
    const pageGroups = groups.slice((page - 1) * pageSize, page * pageSize)

    const rows = pageGroups.map(group => {
        const blocked = isBlocked(group.jid)
        return {
            title: `${blocked ? '🚫' : '🟢'} ${group.subject}`.slice(0, 24),
            description: blocked
                ? 'Filter aktif • tap untuk izinkan adzan'
                : 'Adzan aktif • tap untuk kecualikan grup',
            id: `${prefix}adzanblacklisttoggle ${page} ${group.jid}`
        }
    })
    if (page > 1) rows.push({
        title: '⬅️ Halaman sebelumnya',
        description: `Kembali ke halaman ${page - 1}`,
        id: `${prefix}blacklistadzan ${page - 1}`
    })
    if (page < totalPages) rows.push({
        title: '➡️ Halaman berikutnya',
        description: `Lihat halaman ${page + 1} dari ${totalPages}`,
        id: `${prefix}blacklistadzan ${page + 1}`
    })
    rows.push({
        title: '🔄 Muat ulang daftar',
        description: 'Perbarui status filter notifikasi adzan',
        id: `${prefix}blacklistadzan ${page}`
    })

    const heading = '🕌 FILTER NOTIFIKASI ADZAN'
    const detail =
        `${heading}\n\n` +
        `${displayNotice ? `${displayNotice}\n\n` : ''}` +
        `Pilih grup pada tombol *Kelola filter adzan* untuk mengubah status.\n` +
        `🟢 = notifikasi adzan tetap dikirim\n` +
        `🚫 = notifikasi adzan dikecualikan untuk grup ini\n\n` +
        `📄 Halaman: ${page}/${totalPages}\n` +
        `👥 Total grup: ${groups.length}\n` +
        `🚫 Grup dikecualikan: ${blockedCount}\n\n` +
        `Filter hanya memengaruhi notifikasi Auto Adzan dan penutupan grup otomatis; fitur grup lainnya tidak diubah.`

    const manualRows = pageGroups.map(group =>
        `• ${isBlocked(group.jid) ? '🚫' : '🟢'} ${group.subject}\n  ${prefix}adzanblacklisttoggle ${page} ${group.jid}`
    ).join('\n')
    const fallbackText =
        `${detail}\n\nDaftar manual halaman ${page}:\n${manualRows}\n\n` +
        (page > 1 ? `Halaman sebelumnya: ${prefix}blacklistadzan ${page - 1}\n` : '') +
        (page < totalPages ? `Halaman berikutnya: ${prefix}blacklistadzan ${page + 1}` : '')

    return sendWaListMenu({
        text: detail,
        title: 'Kelola filter adzan',
        footer: 'Xeryuu-MD V16 • Filter Auto Adzan',
        sections: [{ title: `Grup • halaman ${page}/${totalPages}`.slice(0, 24), rows }],
        imageBuffer: readProjectAsset('media/xeryuu.png'),
        fallbackText
    })
}

