const sendStoreProductSelectionMenu = async (kind = 'all', requestedPage = 1) => {
    const filters = {
        all: { type: null, heading: '🛍️ KATALOG SEMUA PRODUK', title: 'Pilih produk' },
        panel: { type: 'panel', heading: '🖥️ PTERODACTYL PANEL', title: 'Pilih paket panel' },
        jadibot: { type: 'jadibot', heading: '🤖 LAYANAN JADIBOT', title: 'Pilih paket Jadibot' },
        rental: { type: 'rental', heading: '👥 SEWA BOT', title: 'Pilih durasi sewa' }
    }
    const config = filters[String(kind || 'all').toLowerCase()] || filters.all
    const products = storeService.products()
        .filter(product => !config.type || product.type === config.type)
        .sort((a, b) => Number(a.price) - Number(b.price) || a.name.localeCompare(b.name))

    if (!products.length) {
        return replyV1(`📦 Produk belum tersedia untuk kategori ${config.heading.toLowerCase()}. Silakan hubungi owner.`)
    }

    const pageSize = 7
    const totalPages = Math.max(1, Math.ceil(products.length / pageSize))
    const page = Math.max(1, Math.min(totalPages, Math.floor(Number(requestedPage) || 1)))
    const current = products.slice((page - 1) * pageSize, page * pageSize)
    const rows = current.map(product => {
        const duration = product.durationDays ? ` • ${product.durationDays} hari` : ''
        const stock = Number(product.stock) > 0 ? `${product.stock} tersedia` : 'Stok habis'
        const label = product.type === 'panel' ? '🖥️' : product.type === 'jadibot' ? '🤖' : '👥'
        return {
            title: `${label} ${product.name}`.slice(0, 24),
            description: `Rp${storeService.formatMoney(product.price)} • ${stock}${duration}`,
            id: `${prefix}belistore ${product.key}`
        }
    })

    if (page > 1) rows.push({
        title: '⬅️ Halaman sebelumnya',
        description: `Kembali ke halaman ${page - 1}`,
        id: `${prefix}storepage ${config.type || 'all'} ${page - 1}`
    })
    if (page < totalPages) rows.push({
        title: '➡️ Halaman berikutnya',
        description: `Lihat halaman ${page + 1} dari ${totalPages}`,
        id: `${prefix}storepage ${config.type || 'all'} ${page + 1}`
    })
    rows.push({ title: '🏬 Kembali ke Store', description: 'Pilih kategori layanan lain', id: `${prefix}store` })

    const artworkKey = config.type === 'panel' ? 'panel'
        : config.type === 'jadibot' ? 'jadibot'
        : config.type === 'rental' ? 'sewabot'
        : 'store'
    const fallbackLines = current.map(product =>
        `• ${product.name} — Rp${storeService.formatMoney(product.price)} (${Number(product.stock) > 0 ? `${product.stock} stok` : 'habis'})\n  ${prefix}belistore ${product.key}`
    ).join('\n')
    const body =
        `${config.heading}\n\n` +
        `Temukan paket yang sesuai kebutuhanmu.\n\n` +
        `📄 Halaman ${page}/${totalPages} • ${products.length} produk\n` +
        `💳 Harga ditampilkan sebelum checkout. Pesanan baru dianggap lunas setelah pembayaran tervalidasi.`

    return sendWaListMenu({
        text: body,
        title: config.title,
        artworkKey,
        footer: 'Xeryuu Store • Pilih paket dengan mudah',
        sections: [{ title: 'Paket tersedia', rows }],
        fallbackText: `${body}\n\n${fallbackLines}\n\nKetik ${prefix}store untuk kembali ke menu utama.`
    })
}

