const resolveOwnerWhatsAppJid = () => {
    const rawOwner = Array.isArray(global.owner) ? global.owner[0] : global.owner
    const raw = String(rawOwner || '').trim()
    if (!raw) return ''
    if (/@s\.whatsapp\.net$|@g\.us$/i.test(raw)) return raw
    const digits = raw.replace(/\D/g, '')
    return digits.length >= 8 ? `${digits}@s.whatsapp.net` : ''
}

const unwrapWhatsAppMessageContent = input => {
    let content = input?.message || input || {}
    for (let depth = 0; depth < 5; depth++) {
        const next = content?.ephemeralMessage?.message ||
            content?.viewOnceMessage?.message ||
            content?.viewOnceMessageV2?.message ||
            content?.documentWithCaptionMessage?.message
        if (!next) break
        content = next
    }
    return content
}

const readConvertPulsaProofImage = async imageMessage => {
    const announced = Number(imageMessage?.fileLength || 0)
    const maxBytes = 8 * 1024 * 1024
    if (announced > maxBytes) throw new Error('Ukuran bukti terlalu besar. Kirim foto maksimal 8 MB.')
    const stream = await downloadContentFromMessage(imageMessage, 'image')
    const chunks = []
    let total = 0
    for await (const chunk of stream) {
        const item = Buffer.from(chunk)
        total += item.length
        if (total > maxBytes) throw new Error('Ukuran bukti terlalu besar. Kirim foto maksimal 8 MB.')
        chunks.push(item)
    }
    const buffer = Buffer.concat(chunks)
    if (!buffer.length) throw new Error('Foto bukti kosong atau tidak bisa dibaca. Coba kirim ulang sebagai foto biasa.')
    return buffer
}

const handleConvertPulsaProofMedia = async inboundMessage => {
    if (!inboundMessage || inboundMessage.key?.fromMe || inboundMessage.isGroup) return false
    const session = convertPulsaSessionForCurrentUser()
    if (!session || session.step !== 'proof_upload') return false
    const content = unwrapWhatsAppMessageContent(inboundMessage)
    const imageMessage = content?.imageMessage || inboundMessage.msg?.imageMessage
    if (!imageMessage) return false
    const ref = String(session.proofRef || '').trim().toUpperCase()
    const tx = convertPulsaService.findOrder(ref)
    const restoreSession = () => {
        const returnStep = String(session.proofReturnStep || '')
        if (returnStep) saveConvertPulsaSession({ step: returnStep, proofRef: '', proofReturnStep: '' })
        else convertPulsaService.clearSession('whatsapp', inboundMessage.sender)
    }
    if (!tx || tx.channel !== 'whatsapp' || tx.userId !== inboundMessage.sender || !convertPulsaProofAllowed(tx)) {
        restoreSession()
        await replyV1('⚠️ Sesi bukti tidak valid, instruksi resmi belum tersedia, atau order sudah tidak aktif. Status PesanJasa tidak diubah. Cek status/riwayat terlebih dahulu.')
        return true
    }
    if (Number(tx.proofCount || 0) >= 3 || Date.now() - Number(tx.proofSubmittedAt || 0) < 15000) {
        await replyV1('⚠️ Batas bukti sudah tercapai atau bukti sebelumnya baru saja dikirim. Tidak ada file baru yang diteruskan. Cek status transaksi atau hubungi owner.')
        return true
    }
    const ownerJid = resolveOwnerWhatsAppJid()
    if (!ownerJid) {
        await replyV1('❌ Kontak owner belum terkonfigurasi dengan benar. Bukti belum diteruskan dan status transaksi tidak diubah.')
        return true
    }

    let proofClaim = null
    let forwarded = false
    let updated = null
    try {
        proofClaim = convertPulsaService.claimProof(tx.ref, { channel: 'whatsapp', submitter: inboundMessage.sender })
        const buffer = await readConvertPulsaProofImage(imageMessage)
        const caption = `🧾 BUKTI CONVERT PULSA — REVIEW MANUAL
Referensi lokal: ${tx.ref}
Referensi PesanJasa: ${tx.providerTrxId}
Operator: ${tx.operatorName || '-'}
Nominal pulsa: Rp${convertPulsaService.formatMoney(tx.amount)}
Status provider: ${convertPulsaStatusLabel(tx.status)}
Pengirim WhatsApp: ${inboundMessage.sender}
Catatan: bukti bot-side untuk review manual; tidak dikirim ke API PesanJasa.`
        await conn.sendMessage(ownerJid, { image: buffer, caption })
        forwarded = true
        updated = convertPulsaService.recordProof(tx.ref, {
            channel: 'whatsapp', submitter: inboundMessage.sender, claimToken: proofClaim.token
        })
    } catch (error) {
        if (proofClaim?.token) {
            try { convertPulsaService.releaseProofClaim(tx.ref, proofClaim.token) } catch (releaseError) {
                console.error('[CONVERT PULSA PROOF RELEASE WA]', releaseError?.stack || releaseError)
            }
        }
        console.error('[CONVERT PULSA PROOF WA]', error?.stack || error)
        if (forwarded) {
            restoreSession()
            await replyV1(`⚠️ Owner sudah menerima foto untuk review manual, tetapi metadata bukti tidak berhasil disimpan: ${error?.message || error}. Status PesanJasa tidak diubah. Referensi: ${tx.ref}. Jangan kirim pulsa ulang.`)
        } else {
            await replyV1(`❌ Bukti belum diteruskan ke owner: ${error?.message || error}. Sesi upload tetap aktif agar kamu bisa mencoba lagi. Status PesanJasa tidak diubah.`)
        }
        return true
    }

    restoreSession()
    try {
        await sendConvertPulsaTransaction(updated)
    } catch (error) {
        console.error('[CONVERT PULSA PROOF WA STATUS VIEW]', error?.stack || error)
        await replyV1(`✅ Bukti telah diteruskan ke owner untuk pemeriksaan manual. Status provider tidak berubah otomatis. Referensi: ${updated.ref}. Gunakan ${prefix}cpstatus ${updated.ref} untuk memeriksa status.`)
    }
    return true
}

const formatConvertPulsaTransaction = tx => {
    const status = String(tx?.status || 'UNKNOWN').toUpperCase()
    let text = `╭─═⪩ 💱 STATUS CONVERT PULSA ⪨═─╮\n` +
        `│ Ref lokal: ${tx.ref}\n` +
        `│ Ref provider: ${tx.providerTrxId || '-'}\n` +
        `│ Operator: ${tx.operatorName || '-'}\n` +
        `│ Pulsa: Rp${convertPulsaService.formatMoney(tx.amount)}\n` +
        `│ Estimasi e-wallet: ${tx.estimatedAmount == null ? 'Tidak tersedia' : `Rp${convertPulsaService.formatMoney(tx.estimatedAmount)}`}\n` +
        `│ Status: ${convertPulsaStatusLabel(status)}\n` +
        `│ Bukti: ${convertPulsaProofStatusLabel(tx)}\n` +
        `╰─═─═─═─═─═─═⪩\n`
    const hasInstructions = convertPulsaService.hasOfficialInstructions(tx)
    const terminalOrUnsafe = ['SUCCESS', 'FAILED', 'EXPIRED', 'CANCELLED', 'CREATE_FAILED', 'REVIEW_REQUIRED'].includes(status)
    if (!terminalOrUnsafe && hasInstructions) {
        text += `\n📲 INSTRUKSI PESANJASA\n`
        if (tx.receiverNumber) text += `Nomor tujuan transfer pulsa: ${tx.receiverNumber}\n`
        if (tx.ussd) text += `Kode/USSD: ${tx.ussd}\n`
        if (tx.instructionText) text += `Petunjuk provider: ${tx.instructionText}\n`
        text += `\nPastikan nominal dan nomor sesuai instruksi. Jangan mengirim pulsa ke nomor selain yang diberikan provider. Setelah transfer, tunggu status provider berubah; jangan mengirim ulang.`
    } else if (['WAITING_TRANSFER', 'PENDING'].includes(status)) {
        text += `\n⚠️ PesanJasa belum memberikan nomor tujuan/USSD yang dapat dikenali. JANGAN kirim pulsa dulu. Simpan referensi dan hubungi owner/provider untuk pemeriksaan.`
    } else if (status === 'PROCESSING') {
        text += `\nPulsa sudah terdeteksi atau pencairan sedang diproses menurut status provider. Jangan mengirim pulsa lagi dan tunggu pembaruan berikutnya.`
    } else if (status === 'SUCCESS') {
        text += `\n✅ Provider melaporkan transaksi selesai. Periksa saldo e-wallet tujuan.`
    } else if (status === 'REVIEW_REQUIRED') {
        text += `\n⚠️ Status pembuatan order belum dapat dipastikan. Jangan transfer pulsa dan jangan buat order duplikat. Minta rekonsiliasi owner/provider.`
    } else if (status === 'CREATE_FAILED' || status === 'FAILED' || status === 'EXPIRED') {
        text += `\nTransaksi tidak berstatus aktif. Pastikan tidak ada transfer pulsa yang sudah dilakukan; bila sudah, hubungi owner/provider sebelum membuat order baru.`
    }
    return text
}

const sendConvertPulsaTransaction = async tx => {
    const text = formatConvertPulsaTransaction(tx)
    const buttons = []
    if (tx.providerTrxId && !convertPulsaService.isTerminal(tx.status) && tx.status !== 'REVIEW_REQUIRED') {
        buttons.push({ title: '🔄 Cek Status', id: `${prefix}cpstatus ${tx.ref}` })
    } else {
        buttons.push({ title: '🔄 Cek Status', id: `${prefix}cpstatus ${tx.ref}` })
    }
    if (convertPulsaProofAllowed(tx) && Number(tx.proofCount || 0) < 3) buttons.push({ title: '🧾 Kirim Bukti', id: `${prefix}cpbukti ${tx.ref}` })
    buttons.push({ title: '💱 Menu Convert', id: `${prefix}convertpulsa` })
    return sendConvertPulsaWaQuickReplyMenu({
        text,
        footer: 'Xeryuu-MD V16 × Sendrich • PesanJasa',
        buttons,
        fallbackText: `${text}\n\nCek status: ${prefix}cpstatus ${tx.ref}`
    })
}

