async function streamToBuffer(stream) {
    const chunks = []

    return new Promise((resolve, reject) => {
        stream.on('data', chunk => chunks.push(chunk))
        stream.on('end', () => resolve(Buffer.concat(chunks)))
        stream.on('error', reject)
    })
}
  
        const resolveTikTokAssetUrl = (value) => {
  const raw = String(value || '').trim();
  if (!raw) return '';
  if (/^https?:\/\//i.test(raw)) return raw;
  if (raw.startsWith('//')) return `https:${raw}`;
  return `https://tikwm.com/${raw.replace(/^\/+/, '')}`;
};

async function downloadTikTokAsset(url, kind = 'video') {
  const target = String(url || '').trim();
  if (!target) throw new Error(`URL ${kind} TikTok kosong`);

  const response = await axios({
    method: 'GET',
    url: target,
    responseType: 'arraybuffer',
    timeout: 45000,
    maxContentLength: 80 * 1024 * 1024,
    maxBodyLength: 80 * 1024 * 1024,
    headers: {
      'Accept': kind === 'video' ? 'video/mp4,video/*;q=0.9,*/*;q=0.8' : 'audio/mpeg,audio/*;q=0.9,*/*;q=0.8',
      'Referer': 'https://www.tikwm.com/',
      'User-Agent': 'Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/116.0.0.0 Mobile Safari/537.36'
    }
  });

  const buffer = Buffer.from(response.data || '');
  if (!buffer.length) throw new Error(`File ${kind} TikTok kosong`);

  const contentType = String(response.headers?.['content-type'] || '').toLowerCase();
  let detected = null;
  try {
    const { fromBuffer } = require('file-type');
    detected = await fromBuffer(buffer);
  } catch {}

  const mime = String(detected?.mime || contentType || '').toLowerCase();
  const validVideo = kind === 'video' && (mime.startsWith('video/') || mime.includes('mp4') || mime.includes('quicktime'));
  const validAudio = kind === 'audio' && (mime.startsWith('audio/') || mime.includes('mp3') || mime.includes('mpeg') || mime.includes('mp4'));

  // TikWM/CDN can return an HTML/error page with HTTP 200. Never send that as media.
  if (!(validVideo || validAudio)) {
    const preview = buffer.subarray(0, 160).toString('utf8').replace(/\s+/g, ' ').trim();
    throw new Error(`Respons ${kind} bukan file media (${mime || 'unknown'}${preview ? `: ${preview.slice(0, 80)}` : ''})`);
  }

  return { buffer, mime: detected?.mime || (kind === 'video' ? 'video/mp4' : 'audio/mpeg') };
}

        async function tiktok2(query) {
  try {
    const url = String(query || '').trim();
    if (!/^https?:\/\//i.test(url)) {
      throw new Error('URL TikTok tidak valid');
    }

    const encodedParams = new URLSearchParams();
    encodedParams.set('url', url);
    encodedParams.set('hd', '1');

    const response = await axios({
      method: 'POST',
      url: 'https://tikwm.com/api/',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
        'Accept': 'application/json, text/plain, */*',
        'Cookie': 'current_language=en',
        'Origin': 'https://www.tikwm.com',
        'Referer': 'https://www.tikwm.com/',
        'User-Agent': 'Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/116.0.0.0 Mobile Safari/537.36'
      },
      data: encodedParams,
      timeout: 30000
    });

    if (!response.data || Number(response.data.code) !== 0 || !response.data.data) {
      throw new Error(response.data?.msg || 'API TikWM Error / Video tidak ditemukan');
    }

    const v = response.data.data;
    return {
      title: v.title || 'TikTok Video',
      cover: resolveTikTokAssetUrl(v.cover),
      origin_cover: resolveTikTokAssetUrl(v.origin_cover),
      no_watermark: resolveTikTokAssetUrl(v.play),
      no_watermark_hd: resolveTikTokAssetUrl(v.hdplay),
      watermark: resolveTikTokAssetUrl(v.wmplay),
      music: resolveTikTokAssetUrl(v.music || v.music_info?.play),
      duration: Number(v.duration || 0),
      images: Array.isArray(v.images) ? v.images.map(resolveTikTokAssetUrl).filter(Boolean) : []
    };

  } catch (err) {
    console.error('[TIKTOK API ERROR]', err?.stack || err);
    return { error: true, message: err?.message || 'Gagal mengambil data TikTok' };
  }
}
