async function getLyrics(title, artist = '', album = '', duration = 0) {
    try {
        if (!title) return null

        const clean = (value = '') => String(value)
            .replace(/https?:\/\/\S+/gi, '')
            .replace(/\[[^\]]*(?:official|audio|video|music video|lyrics?|lyric video|hd|hq|4k|8k|remastered|live|visualizer|topic)[^\]]*\]/gi, '')
            .replace(/\([^)]*(?:official|audio|video|music video|lyrics?|lyric video|hd|hq|4k|8k|remastered|live|visualizer|topic)[^)]*\)/gi, '')
            .replace(/\b(?:official|audio|video|music video|lyrics?|lyric video|hd|hq|4k|8k|remastered|live|visualizer|topic)\b/gi, '')
            .replace(/[|•]+/g, ' ')
            .replace(/\s+/g, ' ')
            .trim()

        const cleanArtist = clean(artist)
        let cleanedTitle = clean(title)

        // Jika judul YouTube berbentuk "Artist - Song", pisahkan secara konservatif.
        let cleanedArtist = cleanArtist
        if (!cleanedArtist && cleanedTitle.includes(' - ')) {
            const parts = cleanedTitle.split(' - ')
            if (parts.length >= 2) {
                const possibleArtist = parts.shift().trim()
                const possibleTitle = parts.join(' - ').trim()
                if (possibleArtist && possibleTitle) {
                    cleanedArtist = possibleArtist
                    cleanedTitle = possibleTitle
                }
            }
        }

        const requestLyrics = async (params, timeout = 12000) => {
            try {
                const response = await axios.get('https://lrclib.net/api/get', {
                    params,
                    timeout,
                    headers: {
                        'User-Agent': 'Xeryuu-Md V16 fix edition (lyrics feature)'
                    },
                    validateStatus: status => status >= 200 && status < 500
                })
                if (response.status !== 200 || !response.data) return null
                return response.data
            } catch (err) {
                console.error('[LRCLIB GET ERROR]', err?.message || err)
                return null
            }
        }

        const searchLyrics = async (params, timeout = 12000) => {
            try {
                const response = await axios.get('https://lrclib.net/api/search', {
                    params,
                    timeout,
                    headers: {
                        'User-Agent': 'Xeryuu-Md V16 fix edition (lyrics feature)'
                    },
                    validateStatus: status => status >= 200 && status < 500
                })
                if (response.status !== 200 || !Array.isArray(response.data)) return []
                return response.data
            } catch (err) {
                console.error('[LRCLIB SEARCH ERROR]', err?.message || err)
                return []
            }
        }

        const toSeconds = value => {
            if (typeof value === 'number' && Number.isFinite(value)) return Math.round(value)
            const str = String(value || '').trim()
            if (!str) return 0
            if (/^\d+(?:\.\d+)?$/.test(str)) return Math.round(Number(str))
            const parts = str.split(':').map(Number)
            if (parts.length === 2 && parts.every(Number.isFinite)) {
                return Math.round(parts[0] * 60 + parts[1])
            }
            if (parts.length === 3 && parts.every(Number.isFinite)) {
                return Math.round(parts[0] * 3600 + parts[1] * 60 + parts[2])
            }
            return 0
        }

        const durationSeconds = toSeconds(duration)

        // Endpoint /api/get lebih presisi karena memakai signature lagu.
        if (cleanedTitle && cleanedArtist) {
            const exactParams = {
                track_name: cleanedTitle,
                artist_name: cleanedArtist
            }
            if (album) exactParams.album_name = clean(album)
            if (durationSeconds >= 1 && durationSeconds <= 3600) {
                exactParams.duration = durationSeconds
            }

            const exact = await requestLyrics(exactParams)
            if (exact && (exact.plainLyrics || exact.syncedLyrics)) {
                return {
                    title: exact.trackName || cleanedTitle,
                    artist: exact.artistName || cleanedArtist,
                    album: exact.albumName || '',
                    duration: exact.duration || durationSeconds || 0,
                    plainLyrics: exact.plainLyrics?.trim() || '',
                    syncedLyrics: exact.syncedLyrics || null
                }
            }
        }

        // Fallback search: q lebih cocok untuk judul YouTube yang berantakan.
        const searches = []
        const pushSearch = params => {
            const key = JSON.stringify(params)
            if (!searches.some(item => item.key === key)) searches.push({ key, params })
        }

        if (cleanedTitle && cleanedArtist) {
            pushSearch({ q: `${cleanedTitle} ${cleanedArtist}` })
            pushSearch({ track_name: cleanedTitle, artist_name: cleanedArtist })
        }
        if (cleanedTitle) {
            pushSearch({ q: cleanedTitle })
            pushSearch({ track_name: cleanedTitle })
        }
        if (title && title !== cleanedTitle) {
            pushSearch({ q: String(title).trim() })
        }

        const normalize = value => String(value || '')
            .toLowerCase()
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/[^\w\s]/g, ' ')
            .replace(/\s+/g, ' ')
            .trim()

        const wantedTitle = normalize(cleanedTitle)
        const wantedArtist = normalize(cleanedArtist)
        let allResults = []

        for (const item of searches) {
            const results = await searchLyrics(item.params)
            allResults.push(...results)
            await new Promise(resolve => setTimeout(resolve, 250))
        }

        if (!allResults.length) return null

        const uniqueResults = allResults.filter((item, index, arr) => {
            const key = `${normalize(item.trackName || '')}|${normalize(item.artistName || '')}|${normalize(item.albumName || '')}`
            return index === arr.findIndex(x => {
                const other = `${normalize(x.trackName || '')}|${normalize(x.artistName || '')}|${normalize(x.albumName || '')}`
                return key === other
            })
        })

        const score = result => {
            const rt = normalize(result.trackName)
            const ra = normalize(result.artistName)
            let points = 0
            if (rt === wantedTitle) points += 100
            else if (rt.includes(wantedTitle) || wantedTitle.includes(rt)) points += 55
            if (wantedArtist) {
                if (ra === wantedArtist) points += 100
                else if (ra.includes(wantedArtist) || wantedArtist.includes(ra)) points += 55
            }
            if (result.plainLyrics?.trim()) points += 40
            if (result.syncedLyrics?.trim()) points += 15
            if (durationSeconds > 0 && Number(result.duration) > 0) {
                const diff = Math.abs(Number(result.duration) - durationSeconds)
                if (diff <= 2) points += 50
                else if (diff <= 10) points += 20
            }
            return points
        }

        uniqueResults.sort((a, b) => score(b) - score(a))

        const best = uniqueResults.find(item =>
            item.plainLyrics?.trim() || item.syncedLyrics?.trim()
        )
        if (!best) return null

        return {
            title: best.trackName || cleanedTitle,
            artist: best.artistName || cleanedArtist,
            album: best.albumName || '',
            duration: best.duration || durationSeconds || 0,
            plainLyrics: best.plainLyrics?.trim() || '',
            syncedLyrics: best.syncedLyrics || null
        }
    } catch (error) {
        console.error('[GET LYRICS ERROR]', error?.stack || error)
        return null
    }
}

// Pilihan lagu .play dilanjutkan ke pilihan format MP3/MP4.
const PLAY_FORMAT_BUTTON_RE = /^xeryuu_play_(mp3|mp4)_([a-f0-9]{12})$/i;

const sendPlayFormatMenu = async (track, stored) => {
    const token = crypto.randomBytes(6).toString('hex');
    stored.stage = 'format';
    stored.selectedTrack = track;
    stored.formatToken = token;
    stored.processing = false;
    stored.formatSelectedAt = Date.now();

    const title = String(track?.title || 'Lagu pilihan').replace(/[\r\n`]/g, ' ').trim().slice(0, 160);
    const artist = String(track?.author?.name || 'Artis tidak diketahui').replace(/[\r\n`]/g, ' ').trim().slice(0, 100);
    const duration = String(track?.timestamp || '-').replace(/[\r\n`]/g, ' ').slice(0, 20);
    const text = `🎧 *LAGU DIPILIH*\n\n` +
        `🎵 Judul: ${title}\n` +
        `👤 Artis/Channel: ${artist}\n` +
        `⏱️ Durasi: ${duration}\n\n` +
        `Tekan *📂 Pilih Format* untuk memilih jenis file yang akan dikirim.\n` +
        `🎵 MP3 — audio saja\n` +
        `🎬 MP4 — video + audio yang dikonversi ke format kompatibel WhatsApp.\n\n` +
        `Pilihan berlaku sampai 10 menit. Jika daftar tidak muncul, balas *mp3* atau *mp4*.`;

    const buttons = [{
        name: 'single_select',
        buttonParamsJson: JSON.stringify({
            title: '📂 Pilih Format',
            sections: [{
                title: 'Format Download',
                rows: [
                    {
                        title: '🎵 MP3 · Audio',
                        description: 'Unduh audio lagu saja',
                        id: `xeryuu_play_mp3_${token}`
                    },
                    {
                        title: '🎬 MP4 · Video HD',
                        description: 'Video + audio • kompatibel WhatsApp',
                        id: `xeryuu_play_mp4_${token}`
                    }
                ]
            }]
        })
    }];

    try {
        const waMessage = generateWAMessageFromContent(m.chat, {
            viewOnceMessage: {
                message: {
                    messageContextInfo: { deviceListMetadata: {}, deviceListMetadataVersion: 2 },
                    interactiveMessage: proto.Message.InteractiveMessage.fromObject({
                        body: proto.Message.InteractiveMessage.Body.fromObject({ text }),
                        footer: proto.Message.InteractiveMessage.Footer.fromObject({ text: 'Xeryuu-Md V16 × Sendrich • Music Downloader' }),
                        header: proto.Message.InteractiveMessage.Header.fromObject({ title: '🎧 Pilih Format Download', hasMediaAttachment: false }),
                        nativeFlowMessage: proto.Message.InteractiveMessage.NativeFlowMessage.fromObject({
                            buttons,
                            messageParamsJson: '{}'
                        })
                    })
                }
            }
        }, { quoted: m, userJid: m.sender });
        await conn.relayMessage(m.chat, waMessage.message, { messageId: waMessage.key.id });
    } catch (interactiveError) {
        console.error('[PLAY FORMAT BUTTON FALLBACK]', interactiveError?.stack || interactiveError?.message || interactiveError);
        await conn.sendMessage(m.chat, { text }, { quoted: m });
    }
};

const processPlayMediaSelection = async (track, format, stored) => {
    const songTitle = String(track?.title || 'Lagu pilihan').replace(/[\r\n`]/g, ' ').trim();
    const songArtist = String(track?.author?.name || '').replace(/[\r\n`]/g, ' ').trim();
    const duration = track?.seconds || track?.duration?.seconds || track?.duration || 0;
    stored.processing = true;

    try {
        if (format === 'mp3') {
            let lyricsSent = false;
            try {
                const lyrics = await getLyrics(songTitle, songArtist, track?.album || '', duration);
                if (lyrics) {
                    let lyricText = lyrics.plainLyrics?.trim() || '';
                    if (!lyricText && lyrics.syncedLyrics) {
                        lyricText = lyrics.syncedLyrics
                            .split('\n')
                            .map(line => line.replace(/^\s*\[[^\]]+\]\s*/, '').trim())
                            .filter(Boolean)
                            .join('\n')
                            .trim();
                    }
                    if (lyricText) {
                        const maxChunk = 3300;
                        const chunks = [];
                        for (let i = 0; i < lyricText.length; i += maxChunk) chunks.push(lyricText.slice(i, i + maxChunk));
                        for (let i = 0; i < chunks.length; i++) {
                            const header = i === 0
                                ? `🎼 LIRIK LAGU\n🎵 ${lyrics.title || songTitle}\n👤 ${lyrics.artist || songArtist || 'Artis tidak diketahui'}\n\n`
                                : `🎼 LIRIK LAGU — LANJUTAN ${i + 1}\n\n`;
                            await conn.sendMessage(m.chat, { text: header + chunks[i] }, { quoted: m });
                        }
                        lyricsSent = true;
                    }
                }
            } catch (lyricsError) {
                console.error('[PLAY LYRICS ERROR]', lyricsError?.stack || lyricsError?.message || lyricsError);
            }

            if (!lyricsSent) {
                await conn.sendMessage(m.chat, {
                    text: `\`\`\`🎼 Lirik untuk ${songTitle} belum ditemukan.\n⏳ Audio tetap sedang disiapkan...\`\`\``
                }, { quoted: m }).catch(() => {});
            }

            const downloaded = await downloadYouTubeAudio(track.url);
            if (!downloaded?.buffer || !Buffer.isBuffer(downloaded.buffer) || downloaded.buffer.length < 1024) {
                throw new Error('Data audio kosong atau tidak valid.');
            }
            const safeTitle = String(downloaded.title || songTitle || 'Xeryuu-Audio')
                .replace(/[\\/:*?"<>|\r\n]/g, '_')
                .slice(0, 160);
            await conn.sendMessage(m.chat, {
                audio: downloaded.buffer,
                mimetype: downloaded.mimetype || 'audio/mpeg',
                fileName: `${safeTitle}.${downloaded.ext || 'mp3'}`,
                ptt: false
            }, { quoted: m });
        } else if (format === 'mp4') {
            await conn.sendMessage(m.chat, {
                text: `🎬 *MENYIAPKAN VIDEO MP4*\n\n🎵 ${songTitle}\n⏳ Sedang mengunduh video dan menyatukan audio. Mohon tunggu sampai file siap dikirim.`
            }, { quoted: m });

            // Resolve the downloader lazily as a compatibility fallback. This also
            // handles deployments where xeryuu.js was updated but the module cache
            // or an older music-downloader.js export is still being used.
            let videoDownloader = downloadYouTubeVideo;
            if (typeof videoDownloader !== 'function') {
                try {
                    const musicDownloaderModule = require('./library/music-downloader.js');
                    videoDownloader = musicDownloaderModule?.downloadYouTubeVideo;
                } catch (loadError) {
                    console.error('[PLAY MP4 DOWNLOADER LOAD ERROR]', loadError?.stack || loadError?.message || loadError);
                }
            }
            if (typeof videoDownloader !== 'function') {
                throw new Error('Fungsi downloadYouTubeVideo tidak tersedia. Pastikan library/music-downloader.js versi terbaru ikut terpasang, lalu restart bot.');
            }
            const downloaded = await videoDownloader(track.url);
            if (!downloaded?.buffer || !Buffer.isBuffer(downloaded.buffer) || downloaded.buffer.length < 1024) {
                throw new Error('Data video kosong atau tidak valid.');
            }
            const safeTitle = String(downloaded.title || songTitle || 'Xeryuu-Video')
                .replace(/[\\/:*?"<>|\r\n]/g, '_')
                .slice(0, 160);
            const qualityLabel = String(downloaded.quality || 'Kualitas terbaik yang tersedia').replace(/[\r\n]/g, ' ').slice(0, 40);
            await conn.sendMessage(m.chat, {
                video: downloaded.buffer,
                mimetype: 'video/mp4',
                fileName: `${safeTitle}.mp4`,
                caption: `🎬 *${songTitle}*\n👤 ${songArtist || 'Artis tidak diketahui'}\n📺 ${qualityLabel}`,
                gifPlayback: false
            }, { quoted: m });
        } else {
            throw new Error('Format download tidak dikenal.');
        }

        delete global.playSearch[playSessionKey];
        await conn.sendMessage(m.chat, { react: { text: '✅', key: m.key } }).catch(() => {});
        return true;
    } catch (error) {
        console.error(`[PLAY ${String(format || '').toUpperCase()} DOWNLOAD ERROR]`, error?.stack || error);
        if (global.playSearch?.[playSessionKey]) {
            global.playSearch[playSessionKey].processing = false;
        }
        await conn.sendMessage(m.chat, { react: { text: '❌', key: m.key } }).catch(() => {});
        const safeError = String(error?.message || '').replace(/[\r\n]/g, ' ').slice(0, 180);
        if (format === 'mp4') {
            await replyV1(`❌ Video MP4 belum berhasil dikirim. Penyedia video mungkin sedang bermasalah atau ukuran video terlalu besar. Coba tekan MP4 sekali lagi beberapa saat nanti.${safeError ? `\nDetail: ${safeError}` : ''}`);
        } else {
            await replyV1(`❌ Audio gagal dikirim. Silakan pilih MP3 lagi untuk mencoba ulang.${safeError ? `\nDetail: ${safeError}` : ''}`);
        }
        return false;
    }
};

const currentPlayState = global.playSearch?.[playSessionKey];
const playFormatButtonMatch = String(body || '').trim().match(PLAY_FORMAT_BUTTON_RE);
if (playFormatButtonMatch) {
    const requestedFormat = playFormatButtonMatch[1].toLowerCase();
    const requestedToken = playFormatButtonMatch[2].toLowerCase();
    const stored = global.playSearch?.[playSessionKey];
    if (!stored || stored.stage !== 'format' || stored.formatToken !== requestedToken) {
        return replyV1('⚠️ Pilihan format ini sudah kedaluwarsa atau bukan milik sesi kamu. Jalankan .play lagi untuk memilih lagu baru.');
    }
    if (stored.chat !== m.chat || stored.sender !== m.sender || Date.now() - Number(stored.createdAt || 0) > 10 * 60 * 1000) {
        delete global.playSearch[playSessionKey];
        return replyV1('⚠️ Pilihan lagu sudah kedaluwarsa. Silakan gunakan .play lagi.');
    }
    if (stored.processing) return replyV1('⏳ Lagu sedang diproses. Tunggu sampai download selesai ya.');
    if (!stored.selectedTrack?.url || !normalizeYouTubeUrl(stored.selectedTrack.url)) {
        delete global.playSearch[playSessionKey];
        return replyV1('❌ Link lagu tidak valid. Silakan jalankan .play lagi.');
    }
    await processPlayMediaSelection(stored.selectedTrack, requestedFormat, stored);
    return;
}

// Fallback teks jika tombol format tidak muncul di WhatsApp pengguna.
if (currentPlayState?.stage === 'format' && /^(?:mp3|audio|mp4|video)$/i.test(String(body || '').trim())) {
    if (Date.now() - Number(currentPlayState.createdAt || 0) > 10 * 60 * 1000) {
        delete global.playSearch[playSessionKey];
        return replyV1('⚠️ Pilihan lagu sudah kedaluwarsa. Silakan gunakan .play lagi.');
    }
    if (currentPlayState.processing) return replyV1('⏳ Lagu sedang diproses. Tunggu sampai download selesai ya.');
    if (!currentPlayState.selectedTrack?.url || !normalizeYouTubeUrl(currentPlayState.selectedTrack.url)) {
        delete global.playSearch[playSessionKey];
        return replyV1('❌ Link lagu tidak valid. Silakan jalankan .play lagi.');
    }
    const requestedFormat = /^(?:mp3|audio)$/i.test(String(body || '').trim()) ? 'mp3' : 'mp4';
    await processPlayMediaSelection(currentPlayState.selectedTrack, requestedFormat, currentPlayState);
    return;
}

// Jawaban angka memilih lagu terlebih dahulu; format audio/video dipilih sesudahnya.
if (currentPlayState && /^\d+$/.test(String(body || '').trim())) {
    const stored = currentPlayState;
    const data = Array.isArray(stored) ? stored : stored?.results;
    const expectedChat = Array.isArray(stored) ? m.chat : stored?.chat;
    const expectedSender = Array.isArray(stored) ? m.sender : stored?.sender;
    const createdAt = Array.isArray(stored) ? 0 : Number(stored?.createdAt || 0);

    if (!Array.isArray(data) || expectedChat !== m.chat || expectedSender !== m.sender ||
        (createdAt && Date.now() - createdAt > 10 * 60 * 1000)) {
        delete global.playSearch[playSessionKey];
        return replyV1('⚠️ Pilihan lagu sudah kedaluwarsa. Silakan gunakan .play lagi.');
    }
    if (stored?.processing) return replyV1('⏳ Pilihan lagu sedang diproses. Tunggu sebentar ya.');
    if (stored?.stage === 'format') {
        return replyV1('🎧 Lagu sudah dipilih. Tekan tombol *📂 Pilih Format*, lalu pilih MP3 atau MP4. Kamu juga bisa membalas `mp3` / `mp4`.');
    }

    const nomor = parseInt(String(body).trim(), 10);
    if (nomor < 1 || nomor > data.length) return replyV1(`❌ Pilih nomor 1-${data.length}`);
    const selectedTrack = data[nomor - 1];
    if (!selectedTrack?.url || !normalizeYouTubeUrl(selectedTrack.url)) {
        return replyV1('❌ Link lagu tidak valid. Silakan jalankan .play lagi.');
    }
    await sendPlayFormatMenu(selectedTrack, stored);
    return;
}
