const MAX_DEOBF_SIZE = 1 * 1024 * 1024
function simpleDeobfuscate(code) {
    if (!code) return ''
    let result = String(code)
    result = result
        .replace(/\r\n/g, '\n')
        .replace(/\r/g, '\n')
        .replace(/\t/g, '    ')
    result = result
        .replace(/[ ]{2,}/g, ' ')
        .replace(/\n{3,}/g, '\n\n')
    result = result
        .replace(/\{/g, ' {\n')
        .replace(/\}/g, '\n}\n')
        .replace(/;/g, ';\n')
    const lines = result
        .split('\n')
        .map(line => line.trim())
        .filter(Boolean)
    let output = ''
    let indent = 0
    for (let line of lines) {
        if (line.startsWith('}')) {
            indent = Math.max(0, indent - 1)
        }
        output += '    '.repeat(indent) + line + '\n'
        if (line.endsWith('{')) {
            indent++
        }
    }
    return output.trim()
}

