    const isTelegram =
        /(?:https?:\/\/)?(?:www\.)?(?:t\.me|telegram\.me)\/[^\s]+/i.test(msgBody)
    const isWhatsApp =
        /(?:https?:\/\/)?(?:www\.)?(?:wa\.me|chat\.whatsapp\.com|whatsapp\.com\/channel)\/[^\s]+/i.test(msgBody)
