 //
 function autoUnAfk(conn, m, _afk, fs, qtoko) {
    if (!m?.isGroup || !m?.sender || !Array.isArray(_afk)) return
    if (m?.key?.fromMe) return
    const index = _afk.findIndex(v => v.id === m.sender)
    if (index === -1) return

    const data = _afk[index]
    const duration = Math.max(0, Date.now() - Number(data.time || Date.now()))
    const seconds = Math.floor(duration / 1000)
    const minutes = Math.floor(seconds / 60)
    const hours = Math.floor(minutes / 60)
    const days = Math.floor(hours / 24)
    const waktu = days > 0 ? `${days} hari ${hours % 24} jam`
        : hours > 0 ? `${hours} jam ${minutes % 60} menit`
        : minutes > 0 ? `${minutes} menit ${seconds % 60} detik`
        : `${seconds} detik`

    _afk.splice(index, 1)
    try {
        fs.writeFileSync(projectPath('library', 'database', 'user.json'), JSON.stringify(_afk, null, 2))
    } catch (e) {
        console.error('[AFK SAVE ERROR]', e)
    }   

    conn.sendMessage(m.chat, {
        text: `@${m.sender.split('@')[0]} sudah tidak AFK lagi 😎\n\n*AFK selama:* ${waktu}\n*Reason:* ${data.reason || 'Tidak ada alasan'}`,
        mentions: [m.sender]
    }, { quoted: qtoko }).catch(e => console.error('[AFK UNAFK NOTIFY]', e))
}
