function greeting() {
let time = new Date().toLocaleString("en-US", { timeZone: "Asia/Jakarta" })
let h = new Date(time).getHours()
if (h < 4) return "🌌 Good Night"
if (h < 11) return "🌅 Good Morning"
if (h < 15) return "☀️ Good Afternoon"
if (h < 18) return "🌇 Good Evening"
return "🌙 Good Night"
}

