async function sendRichGameMenu(page = 1) {
    const games = listRichHtmlGames()
    const pageSize = 8
    const totalPages = Math.max(1, Math.ceil(games.length / pageSize))
    const currentPage = Math.max(1, Math.min(totalPages, Math.floor(Number(page) || 1)))
    const startIndex = (currentPage - 1) * pageSize
    const pageGames = games.slice(startIndex, startIndex + pageSize)
    const rows = pageGames.map(game => ({
        title: `🎮 ${String(game.title || game.key).replace(/[\r\n]/g, ' ').slice(0, 22)}`,
        description: `${prefix}richgame ${game.key}${game.aliases?.length ? ` • alias: ${game.aliases.slice(0, 2).join(', ')}` : ''}`.slice(0, 72),
        id: `${prefix}richgame ${game.key}`
    }))

    // Maksimal 10 baris agar menu tetap kompatibel dengan batas list WhatsApp.
    if (currentPage > 1) rows.push({
        title: '⬅️ Halaman Sebelumnya',
        description: `Kembali ke halaman ${currentPage - 1}`,
        id: `${prefix}richgamepage ${currentPage - 1}`
    })
    if (currentPage < totalPages) rows.push({
        title: '➡️ Halaman Berikutnya',
        description: `Lihat game halaman ${currentPage + 1}`,
        id: `${prefix}richgamepage ${currentPage + 1}`
    })

    const bodyText =
        `🎮 RICH GAME MENU\n` +
        `Pilih game pada tombol di bawah untuk langsung membukanya.\n\n` +
        `📄 Halaman ${currentPage}/${totalPages} • ${games.length} game tersedia\n` +
        `💡 Baris pilihan dapat ditekan; teks instruksi ada di bagian atas menu.`

    const waMessage = generateWAMessageFromContent(m.chat, {
        viewOnceMessage: {
            message: {
                messageContextInfo: { deviceListMetadata: {}, deviceListMetadataVersion: 2 },
                interactiveMessage: proto.Message.InteractiveMessage.fromObject({
                    body: proto.Message.InteractiveMessage.Body.fromObject({ text: bodyText }),
                    footer: proto.Message.InteractiveMessage.Footer.fromObject({ text: 'Xeryuu-Md V16 × Sendrich • Rich HTML Games' }),
                    header: proto.Message.InteractiveMessage.Header.fromObject({ title: '🎮 Pilih Rich Game', hasMediaAttachment: false }),
                    nativeFlowMessage: proto.Message.InteractiveMessage.NativeFlowMessage.fromObject({
                        buttons: [{
                            name: 'single_select',
                            buttonParamsJson: JSON.stringify({
                                title: `Pilih Game (${currentPage}/${totalPages})`,
                                sections: [{ title: 'Game tersedia', rows }]
                            })
                        }],
                        messageParamsJson: '{}'
                    })
                })
            }
        }
    }, { quoted: m, userJid: m.sender })

    await conn.relayMessage(m.chat, waMessage.message, { messageId: waMessage.key.id })
    return currentPage
}

function richGameMenuFallback(page = 1) {
    const games = listRichHtmlGames()
    const pageSize = 8
    const totalPages = Math.max(1, Math.ceil(games.length / pageSize))
    const currentPage = Math.max(1, Math.min(totalPages, Math.floor(Number(page) || 1)))
    const pageGames = games.slice((currentPage - 1) * pageSize, currentPage * pageSize)
    let out = `🎮 RICH GAME MENU • HALAMAN ${currentPage}/${totalPages}\n\n`
    for (const game of pageGames) out += `• ${prefix}richgame ${game.key} — ${game.title}\n`
    if (currentPage < totalPages) out += `\n➡️ Halaman berikutnya: ${prefix}richgamepage ${currentPage + 1}`
    if (currentPage > 1) out += `\n⬅️ Halaman sebelumnya: ${prefix}richgamepage ${currentPage - 1}`
    out += `\n\nPilih game dari daftar di atas.`
    return out
}

async function sendPurchaseMethodMenu(intent) {
    const token = String(intent.token)
    const isNokos = intent.type === 'NOKOS'
    let intentStatus = String(intent.status || '').toUpperCase()
    // Recover after restart if invoice creation completed but the intent save/menu send was interrupted.
    if (intentStatus === 'QRIS_CREATING' && Date.now() - Number(intent.updatedAt || intent.createdAt || 0) > 60000) {
        const invoice = depositService.findByOrderRef?.(token)
        if (invoice) {
            const invoiceStatus = String(invoice.status || '').toUpperCase()
            const nextStatus = ['PAID', 'SUCCESS', 'SETTLED'].includes(invoiceStatus) ? 'QRIS_PAID' : ['EXPIRED', 'FAILED', 'CANCELED', 'CANCELLED'].includes(invoiceStatus) ? 'EXPIRED' : 'WAITING_PAYMENT'
            intent = purchasePayment.saveIntent({ ...intent, status: nextStatus, paymentMethod: 'QRIS', paymentRef: invoice.merchantRef, paymentCreatedAt: invoice.createdAt, paymentExpiredAt: invoice.expiredAt })
            intentStatus = nextStatus
        } else {
            intent = purchasePayment.saveIntent({ ...intent, status: 'QRIS_REVIEW_REQUIRED', reviewReason: 'Proses membuat invoice terputus dan invoice tidak ditemukan di database lokal; cek dashboard provider terkait sebelum mencoba ulang.', reviewAt: Date.now() })
            intentStatus = 'QRIS_REVIEW_REQUIRED'
        }
    }
    if (intentStatus === 'WAITING_PAYMENT' && intent.paymentRef) return sendPurchaseQr(token, isNokos ? 'NOKOS' : 'TOP UP')
    if (intentStatus === 'EXPIRED') return replyV1(`⚠️ Invoice QRIS untuk token ${token} sudah berakhir menurut status lokal. Pesanan tidak dibuat ulang otomatis. Pastikan status invoice provider final; jika ingin membeli ulang, jalankan perintah pesanan setelah invoice lama benar-benar berakhir.`)
    if (['QRIS_CREATING', 'QRIS_REVIEW_REQUIRED', 'QRIS_PAID', 'PROVIDER_PROCESSING', 'BALANCE_PROCESSING', 'REVIEW_REQUIRED'].includes(intentStatus)) {
        const message = intentStatus === 'QRIS_REVIEW_REQUIRED'
            ? `⚠️ Status pembuatan invoice QRIS belum dapat dipastikan. Jangan membayar invoice lain, jangan mengulangi order, dan jangan mengganti metode pembayaran. Token: ${token}. Owner perlu memeriksa status transaksi pada provider terkait terlebih dahulu.`
            : intentStatus === 'REVIEW_REQUIRED' || intentStatus === 'PROVIDER_PROCESSING'
                ? `⚠️ Pesanan ${token} sedang membutuhkan rekonsiliasi status provider. Jangan membeli ulang sampai owner memastikan hasil transaksi.`
                : intentStatus === 'QRIS_PAID'
                    ? `✅ Pembayaran QRIS untuk token ${token} sudah terdeteksi dan order sedang diproses. Jangan membayar ulang.`
                    : `⏳ Pesanan ${token} sedang diproses. Tunggu status akhir; jangan menekan beli ulang.`
        if (intentStatus === 'QRIS_REVIEW_REQUIRED' && !intent.reviewNoticeSentAt) {
            const marked = purchasePayment.saveIntent({ ...intent, reviewNoticeSentAt: Date.now() })
            await telegramService.notifyOwnerPurchase({ type: 'QRIS INVOICE REVIEW REQUIRED', ref: token, customerName: marked.pushname || pushname || '-', customerJid: marked.jid, sellingPrice: marked.amount, status: 'REVIEW_REQUIRED', refunded: false, createdAt: marked.createdAt, note: marked.reviewReason || 'Periksa dashboard provider terkait; jangan membuat invoice ulang.' }).catch(err => console.error('[QRIS REVIEW OWNER NOTICE]', err?.message || err))
        }
        return replyV1(message)
    }
    const title = isNokos ? '📱 PEMBELIAN NOKOS' : '🎮 PEMBELIAN TOP UP'
    const text =
        `${title}\n\n` +
        `Produk: ${intent.label}\n` +
        `Total: Rp${Number(intent.amount).toLocaleString('id-ID')}\n\n` +
        `Pilih metode pembayaran:\n` +
        `• Saldo Deposit Bot: saldo wallet akan dipotong setelah konfirmasi.\n` +
        `• QRIS Provider: opsi ditampilkan, tetapi belum aktif karena API provider yang tersedia belum menyediakan invoice pembelian langsung yang dapat diverifikasi. Tombolnya tidak akan membuat tagihan atau menarik pembayaran.\n\n` +
        `Token order: ${token}\n` +
        `NasionalPay hanya digunakan untuk deposit saldo bot. QRIS langsung tidak akan dibuat melalui endpoint deposit provider.`
    try {
        const buttons = [
            { name: 'quick_reply', buttonParamsJson: JSON.stringify({ display_text: '💰 SALDO DEPOSIT BOT', id: `${prefix}${isNokos ? 'nokospaybalance' : 'topuppay'} ${isNokos ? token : `balance ${token}`}` }) },
            { name: 'quick_reply', buttonParamsJson: JSON.stringify({ display_text: '📲 QRIS PEMBELIAN', id: `${prefix}${isNokos ? 'nokospayqris' : 'topuppay'} ${isNokos ? token : `qris ${token}`}` }) }
        ]
        const waMessage = generateWAMessageFromContent(m.chat, {
            viewOnceMessage: {
                message: {
                    messageContextInfo: { deviceListMetadata: {}, deviceListMetadataVersion: 2 },
                    interactiveMessage: proto.Message.InteractiveMessage.fromObject({
                        body: proto.Message.InteractiveMessage.Body.fromObject({ text }),
                        footer: proto.Message.InteractiveMessage.Footer.fromObject({ text: 'Xeryuu-Md V16 × Sendrich • Pembayaran aman' }),
                        nativeFlowMessage: proto.Message.InteractiveMessage.NativeFlowMessage.fromObject({ buttons, messageParamsJson: '{}' })
                    })
                }
            }
        }, { quoted: m, userJid: m.sender })
        await conn.relayMessage(m.chat, waMessage.message, { messageId: waMessage.key.id })
        return true
    } catch (error) {
        console.error('[PURCHASE PAYMENT MENU]', error?.stack || error)
        await replyV1(text + `\n\n1. ${prefix}${isNokos ? 'nokospaybalance' : 'topuppay balance'} ${isNokos ? token : token}\n2. ${prefix}${isNokos ? 'nokospayqris' : 'topuppay qris'} ${isNokos ? token : token}`)
        return false
    }
}

async function sendPurchaseQr(token, type) {
    try {
        const created = await purchasePayment.createQrPayment(token, m.sender, pushname)
        const state = String(created.intent?.status || '').toUpperCase()
        if (state === 'FULFILLED') {
            return replyV1(`✅ Pesanan ${type} sudah berhasil diproses. Tidak perlu membayar atau membuat invoice baru.
Ref order: ${created.intent.orderRef || token}`)
        }
        if (state === 'FAILED_REFUNDED') {
            return replyV1(`❌ Pesanan ${type} gagal diproses. Dana Rp${Number(created.intent.amount || 0).toLocaleString('id-ID')} sudah diamankan kembali ke saldo bot. Tidak ada order baru yang dibuat.
Token: ${token}`)
        }
        if (['REVIEW_REQUIRED', 'QRIS_REVIEW_REQUIRED', 'PROVIDER_PROCESSING', 'BALANCE_PROCESSING', 'QRIS_PAID'].includes(state)) {
            if (['REVIEW_REQUIRED', 'QRIS_REVIEW_REQUIRED'].includes(state) && !created.intent.reviewNoticeSentAt) {
                const marked = purchasePayment.saveIntent({ ...created.intent, reviewNoticeSentAt: Date.now() })
                await telegramService.notifyOwnerPurchase({ type: `${type} REVIEW REQUIRED`, ref: marked.orderRef || token, customerName: marked.pushname || pushname || '-', customerJid: marked.jid, sellingPrice: marked.amount, status: state, refunded: false, createdAt: marked.createdAt, note: marked.reviewReason || 'Pembayaran terdeteksi tetapi status fulfillment perlu rekonsiliasi.' }).catch(err => console.error('[QRIS REVIEW OWNER NOTICE]', err?.message || err))
            }
            return replyV1(`⚠️ Pesanan ${type} sudah masuk tahap ${state}, tetapi belum aman untuk menampilkan/membuat QRIS baru. Jangan membayar dua kali. Token: ${token}. Owner akan merekonsiliasi status terlebih dahulu.`)
        }
        const payment = created.payment
        if (!payment) throw new Error('Gateway tidak mengembalikan data invoice. Jangan membuat pesanan ulang; cek status token order.')
        const isPaid = ['PAID', 'SUCCESS', 'SETTLED'].includes(String(payment.status || '').toUpperCase())
        const due = Number(payment.totalPay || payment.paymentAmount || payment.amount || 0)
        const expiry = payment.expiredAt ? new Date(Number(payment.expiredAt)).toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' }) : '-'
        const caption =
            `╭─〔 📲 QRIS PEMBELIAN LANGSUNG 〕\n` +
            `║ Jenis    : ${type}\n` +
            `║ Invoice  : ${payment.merchantRef}\n` +
            `║ Produk   : ${created.intent.label}\n` +
            `║ Total    : Rp${depositService.formatMoney(due)}\n` +
            `║ Status   : ${isPaid ? 'SUDAH DIBAYAR' : payment.status || 'MENUNGGU'}\n` +
            `║ Expired  : ${expiry}\n` +
            `╰────────────────\n\n` +
            (isPaid ? '✅ Pembayaran terdeteksi. Pesanan sedang diproses/akan direkonsiliasi otomatis.' : 'Scan QRIS untuk membayar pesanan ini. Pembayaran ini langsung untuk produk, bukan deposit saldo bot. Jangan membayar dua kali.') +
            (payment.checkoutUrl ? `\n\n🔗 Link pembayaran: ${payment.checkoutUrl}` : '') +
            `\n\nCek status invoice: ${prefix}purchaseqrisstatus ${payment.merchantRef}`
        let image = null
        try { image = await depositService.qrBuffer(payment) } catch (err) { console.error('[PURCHASE QR BUFFER]', err?.message || err) }
        const qrCaption = caption + (image ? '' : (payment.qrString
            ? `\n\nPayload QR tersedia di sistem gateway, tetapi gagal dirender sebagai gambar.`
            : '\n\nGateway tidak mengembalikan gambar QR. Gunakan link invoice jika tersedia atau hubungi owner; jangan buat order ulang.'))
        const canCancel = String(created.intent?.status || '').toUpperCase() === 'WAITING_PAYMENT' && !isPaid
        const actionText = canCancel
            ? 'Pilih tombol di bawah untuk cek status atau membatalkan order. Jika pembatalan berhasil, pesan QRIS ini akan dihapus.'
            : 'Invoice sudah dibayar atau tidak lagi menunggu pembayaran; pembatalan tidak ditawarkan.'
        const combinedText = `${qrCaption}\n\n${actionText}`
        const controlButtons = [{ title: '🔄 Cek Status', id: `${prefix}purchaseqrisstatus ${payment.merchantRef}` }]
        if (canCancel) controlButtons.push({ title: '❌ Batalkan Order', id: `${prefix}purchaseqriscancel ${token}` })
        const fallbackText = `${combinedText}\n\nPerintah manual: ${prefix}purchaseqrisstatus ${payment.merchantRef}${canCancel ? ` atau ${prefix}purchaseqriscancel ${token}` : ''}`
        const combinedMessage = await sendTransactionControlInteractive({
            text: combinedText,
            imageBuffer: image,
            footer: 'Xeryuu-Md V16 × Sendrich • QRIS Pembelian',
            buttons: controlButtons,
            fallbackText
        })
        await persistQrMessageReferences(payment.merchantRef, combinedMessage, null)
        return combinedMessage
    } catch (error) {
        const intent = purchasePayment.getIntent(token)
        if (intent?.status === 'QRIS_REVIEW_REQUIRED') {
            if (!intent.reviewNoticeSentAt) {
                const marked = purchasePayment.saveIntent({ ...intent, reviewNoticeSentAt: Date.now() })
                await telegramService.notifyOwnerPurchase({ type: 'QRIS INVOICE REVIEW REQUIRED', ref: token, customerName: marked.pushname || pushname || '-', customerJid: marked.jid, sellingPrice: marked.amount, status: 'REVIEW_REQUIRED', refunded: false, createdAt: marked.createdAt, note: marked.reviewReason || String(error?.message || error) }).catch(err => console.error('[QRIS REVIEW OWNER NOTICE]', err?.message || err))
            }
            return replyV1(`⚠️ Invoice QRIS lama untuk token ${token} membutuhkan pemeriksaan owner.\n\n${intent.reviewReason || error?.message || 'Status transaksi belum dapat dipastikan.'}\n\nTidak ada invoice baru dibuat dan saldo bot tidak dipotong. Jangan membayar QR lama atau mengganti metode sampai owner mengonfirmasi statusnya.`)
        }
        if (error?.legacyPurchaseInvoiceEnded) return replyV1(`ℹ️ ${error.message}\nTidak ada invoice baru dibuat dan tidak ada saldo dipotong. Buat pesanan baru setelah invoice lama dipastikan berakhir.`)
        if (error?.providerPaymentUnavailable) return replyV1(`⚠️ QRIS pembelian provider belum tersedia. Tidak ada invoice dibuat dan tidak ada pembayaran diproses.\n\n${error.message}\n\nPilih saldo deposit bot untuk melanjutkan pesanan. Token: ${token}.`)
        if (intent?.status === 'AWAITING_METHOD') return replyV1(`❌ QRIS tidak dapat dibuat: ${error?.message || error}\n\nTidak ada pembayaran baru diproses. Token: ${token}.`)
        return replyV1(`❌ QRIS pembelian tidak dapat ditampilkan: ${error?.message || error}\n\nJangan membuat pesanan ulang jika status sudah diproses. Token: ${token}.`)
    }
}

async function notifyWaPurchaseOwner(result) {
    const order = result?.order || result?.tx
    if (!order) return
    const isNokos = result.type === 'NOKOS'
    const txData = isNokos ? {
        type: 'NOKOS', ref: order.ref, customerName: pushname, customerJid: m.sender,
        service: order.service, country: order.country, provider: order.provider, providerId: order.providerId,
        phone: order.phone, activationId: order.activationId || order.providerTransactionId,
        sellingPrice: order.sellingPrice, providerPrice: order.providerCost,
        profit: Number(order.sellingPrice || 0) - Number(order.providerCost || 0), status: order.status,
        refunded: Boolean(order.refunded), createdAt: order.createdAt
    } : {
        type: 'TOPUP', ref: order.ref, customerName: pushname, customerJid: m.sender,
        game: order.game, productName: order.productName,
        destination: `${order.customerNo || ''}${order.zone ? ` | Zone ${order.zone}` : ''}`,
        sellingPrice: order.sellingPrice, providerPrice: order.providerPrice,
        profit: Number(order.sellingPrice || 0) - Number(order.providerPrice || 0), status: order.status,
        sn: order.sn, refunded: Boolean(order.refunded), createdAt: order.createdAt
    }
    await telegramService.notifyOwnerPurchase(txData).catch(err => console.error('[WA PURCHASE OWNER NOTICE]', err?.stack || err))
}

async function handleWaPurchaseBalance(token, type) {
    try {
        const result = await purchasePayment.buyWithBalance(token, m.sender, type)
        if (result.reviewRequired) return replyV1(`⚠️ Pembayaran sudah tercatat, tetapi status provider belum dapat dipastikan. Jangan klik beli lagi. Ref internal: ${result.order?.ref || result.tx?.ref || result.intent?.token}. Owner perlu merekonsiliasi transaksi sebelum tindakan lanjut.`)
        if (result.failed && result.refunded) return replyV1(`❌ Provider menolak pembelian. Refund Rp${depositService.formatMoney(result.intent?.amount || 0)} sudah dikembalikan ke saldo bot. Alasan: ${result.error?.message || result.order?.providerError || 'Provider gagal.'}`)
        if (!result.success || !(result.order || result.tx)) return replyV1(`⚠️ Pesanan belum bisa dipastikan. Jangan melakukan pembelian ulang. Token: ${token}. Hubungi owner untuk pemeriksaan.`)
        const item = result.order || result.tx
        if (type === 'NOKOS') purchasePayment.startNokosWatcher(item)
        if (!result.already) await notifyWaPurchaseOwner(result)
        if (type === 'NOKOS') {
            return replyV1(`╭─〔 📱 ORDER NOKOS 〕\n║ Ref      : ${item.ref}\n║ Service  : ${item.service}\n║ Negara   : ${item.country}\n║ Provider : ${item.provider || '-'}\n║ Nomor    : ${item.phone || '-'}\n║ Harga    : Rp${depositService.formatMoney(item.sellingPrice)}\n║ Status   : ${String(item.status || 'waiting').toUpperCase()}\n╰────────────────\n\nBot akan mengecek OTP otomatis.\nCek: ${prefix}nokosstatus ${item.ref}\nBatalkan: ${prefix}nokoscancel ${item.ref}`)
        }
        return replyV1(`╭─〔 🎮 ORDER TOP UP 〕\n║ Ref     : ${item.ref}\n║ Game    : ${item.game}\n║ Produk  : ${item.productName}\n║ Tujuan  : ${item.customerNo || '-'}${item.zone ? ` | Zone ${item.zone}` : ''}\n║ Harga   : Rp${topupService.formatMoney(item.sellingPrice)}\n║ Status  : ${item.status}\n║ SN      : ${item.sn || '-'}\n╰────────────────\n\n${item.message || 'Transaksi diproses.'}\nCek: ${prefix}topupstatus ${item.ref}`)
    } catch (error) {
        return replyV1(`❌ Pembayaran saldo gagal: ${error?.message || error}\n\nJika saldo belum terpotong, pilih QRIS pembelian. Jika status menunjukkan sedang diproses, jangan membuat order baru.`)
    }
}

// HD2 button sessions are bounded in memory and expire quickly. The pending
// media is cached as bytes so a button tap does not depend on a quoted message
// still being downloadable from WhatsApp.
const HD2_PENDING_TTL = 3 * 60 * 1000;
const HD2_PENDING_MAX_COUNT = 4;
const HD2_PENDING_MAX_BYTES = 64 * 1024 * 1024;
const getHd2SessionKey = (chat = m.chat, sender = m.sender) => `${String(chat || '')}::${String(sender || '')}`;
const pruneHd2Pending = pending => {
    const now = Date.now();
    for (const [key, entry] of pending) {
        if (!entry || entry.expiresAt <= now) pending.delete(key);
    }
    const totalBytes = () => [...pending.values()].reduce((sum, entry) => sum + (entry.buffer?.length || 0), 0);
    while (pending.size > HD2_PENDING_MAX_COUNT || totalBytes() > HD2_PENDING_MAX_BYTES) {
        const oldestKey = pending.keys().next().value;
        if (!oldestKey) break;
        // A newly created entry is placed last; older sessions are evicted first.
        pending.delete(oldestKey);
    }
};
const runHd2Enhancement = async (buffer, mime, option, quoteMessage = m) => {
    conn.hd2Busy = conn.hd2Busy || new Set();
    if (conn.hd2Busy.has(m.sender)) return replyV1('⏳ Proses HD kamu masih berjalan. Tunggu sampai selesai, ya.');
    if (!Buffer.isBuffer(buffer) || !buffer.length) return replyV1('❌ Media tidak tersedia. Kirim ulang foto/video lalu gunakan .hd2.');
    conn.hd2Busy.add(m.sender);
    try {
        if (/^image\//.test(mime)) {
            const scale = String(option || '2').toLowerCase().replace(/x$/, '');
            if (!['2', '4'].includes(scale)) return replyV1('Pilih kualitas foto 2x atau 4x.');
            await replyV1(`✨ Memproses foto ke ${scale}x. AI upscaler akan dicoba lebih dulu; mohon tunggu.`);
            const result = await hdService.enhanceImage(buffer, Number(scale));
            await conn.sendMessage(m.chat, {
                image: result.buffer,
                mimetype: 'image/jpeg',
                caption: `✨ FOTO HD ${result.scale}x\n\n✅ Foto selesai diproses\n🧠 Metode: ${result.provider}\n🔎 Detail dan ketajaman ditingkatkan\n\nXeryuu-Md V16 × Sendrich`
            }, { quoted: quoteMessage || m });
        } else if (/^video\//.test(mime)) {
            const resolution = String(option || '1080').toLowerCase().replace(/p$/, '');
            if (!['720', '1080', '2k', '1440', '4k', '2160'].includes(resolution)) {
                return replyV1('Pilih resolusi video 720p, 1080p, 2K, atau 4K.');
            }
            await replyV1(`🎬 Memproses video ke ${resolution}. Ini bisa memerlukan waktu cukup lama.`);
            const result = await hdService.enhanceVideo(buffer, resolution);
            await conn.sendMessage(m.chat, {
                video: result.buffer,
                mimetype: 'video/mp4',
                fileName: `Xeryuu-HD-${result.resolution}p.mp4`,
                caption: `🎬 VIDEO HD ${result.resolution}p\n\n✅ Video selesai diproses\n🛠️ Metode: ${result.provider}\n✨ Noise dikurangi, detail dan skala ditingkatkan\n\nXeryuu-Md V16 × Sendrich`
            }, { quoted: quoteMessage || m });
        } else {
            return replyV1('❌ Format media tidak dikenal. Balas foto atau video yang didukung.');
        }
    } catch (error) {
        console.error('[HD2 ERROR]', error?.stack || error);
        return replyV1(`❌ Proses HD gagal. ${error?.message || 'Coba lagi dengan file yang lebih kecil atau resolusi lebih rendah.'}`);
    } finally {
        conn.hd2Busy.delete(m.sender);
    }
};
const downloadHd2MediaBuffer = async (quotedMedia) => {
    if (!quotedMedia) throw new Error('Pesan media tidak ditemukan.');
    // Some Baileys message wrappers expose a convenience downloader; the socket itself usually does not.
    if (typeof quotedMedia.download === 'function') {
        const downloaded = await quotedMedia.download();
        if (Buffer.isBuffer(downloaded) && downloaded.length) return downloaded;
    }
    const content = quotedMedia.msg || quotedMedia.message || quotedMedia;
    let mediaType = quotedMedia.mtype || quotedMedia.type || '';
    if (!mediaType || !content[mediaType]) {
        mediaType = getContentType(content) || '';
    }
    const mediaMessage = content[mediaType] || (/^(image|video|audio|sticker)Message$/.test(mediaType) ? content : null) || content.imageMessage || content.videoMessage;
    if (!mediaMessage) throw new Error('Isi pesan bukan media yang bisa diunduh.');
    const stream = await downloadContentFromMessage(mediaMessage, mediaType.replace(/Message$/, '').toLowerCase());
    const chunks = [];
    for await (const chunk of stream) chunks.push(Buffer.from(chunk));
    const buffer = Buffer.concat(chunks);
    if (!buffer.length) throw new Error('Media gagal diunduh dari pesan.');
    return buffer;
};

const cacheHd2MediaAndShowButtons = async (quotedMedia, mime) => {
    conn.hd2Pending = conn.hd2Pending || new Map();
    conn.hd2Preparing = conn.hd2Preparing || new Set();
    const key = getHd2SessionKey();
    if (conn.hd2Preparing.has(key)) return replyV1('⏳ Media kamu sedang disiapkan. Tunggu sebentar, ya.');
    conn.hd2Preparing.add(key);
    try {
        const buffer = await downloadHd2MediaBuffer(quotedMedia);
        if (!Buffer.isBuffer(buffer) || !buffer.length) throw new Error('Media gagal diunduh dari pesan.');
        const limit = /^image\//.test(mime) ? 18 * 1024 * 1024 : 42 * 1024 * 1024;
        if (buffer.length > limit) throw new Error(/^image\//.test(mime) ? 'Foto maksimal 18 MB.' : 'Video maksimal 42 MB.');
        const pending = conn.hd2Pending;
        pruneHd2Pending(pending);
        pending.delete(key);
        // Make room by evicting oldest stored sessions before adding this payload.
        const sizeOfPending = () => [...pending.values()].reduce((sum, entry) => sum + (entry.buffer?.length || 0), 0);
        while (pending.size >= HD2_PENDING_MAX_COUNT || sizeOfPending() + buffer.length > HD2_PENDING_MAX_BYTES) {
            const oldestKey = pending.keys().next().value;
            if (!oldestKey) break;
            pending.delete(oldestKey);
        }
        if (buffer.length > HD2_PENDING_MAX_BYTES) throw new Error('Media terlalu besar untuk menu pilihan HD.');
        pending.set(key, { buffer, mime, expiresAt: Date.now() + HD2_PENDING_TTL });
        const isImage = /^image\//.test(mime);
        const buttons = isImage
            ? [
                { title: '✨ Foto 2x', id: `${prefix}hd2select 2x` },
                { title: '💎 Foto 4x', id: `${prefix}hd2select 4x` }
              ]
            : [
                { title: '📱 720p', id: `${prefix}hd2select 720p` },
                { title: '🎬 1080p', id: `${prefix}hd2select 1080p` },
                { title: '💠 2K', id: `${prefix}hd2select 2k` },
                { title: '💎 4K', id: `${prefix}hd2select 4k` }
              ];
        const menuText = isImage
            ? '✨ PILIH KUALITAS FOTO\n\nPilih tingkat peningkatan yang kamu inginkan.\nAI upscaler akan dicoba lebih dulu.\n\n✨ Foto 2x — seimbang untuk dibagikan\n💎 Foto 4x — resolusi lebih besar\n\n⏳ Pilihan berlaku selama 3 menit.'
            : '🎬 PILIH RESOLUSI VIDEO\n\nPilih resolusi hasil yang kamu inginkan.\nPemrosesan resolusi tinggi membutuhkan waktu lebih lama.\n\n📱 720p — lebih ringan\n🎬 1080p — Full HD\n💠 2K — detail lebih tinggi\n💎 4K — ukuran file lebih besar\n\n⏳ Pilihan berlaku selama 3 menit.';
        return sendWaQuickReplyMenu({
            text: menuText,
            footer: 'Peningkatan kualitas foto dan video',
            buttons,
            fallbackText: `${menuText}\n\nTombol tidak muncul? Ketik ${prefix}hd2select lalu pilih: ${isImage ? '2x atau 4x' : '720p, 1080p, 2k, atau 4k'} (dalam 3 menit).`
        });
    } finally {
        conn.hd2Preparing.delete(key);
    }
};

