   try {
    async function fetchInitialPage(initialUrl) {
      try {
        const axios = require('axios')
        const cheerio = require('cheerio')
        const headers = {
          'User-Agent': 'Mozilla/5.0 (Linux; Android 10; RMX2185 Build/QP1A.190711.020) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/136.0.7103.60 Mobile Safari/537.36',
          'Referer': initialUrl,
        }
        const response = await axios.get(initialUrl, { headers, timeout: 15000, maxContentLength: 5 * 1024 * 1024 })
        const $ = cheerio.load(response.data)
        const csrfToken = $('meta[name="csrf-token"]').attr('content')
        if (!csrfToken) throw new Error('Gagal nemu token keamanan, coba lagi!')
        let cookies = ''
        if (response.headers['set-cookie']) {
          cookies = response.headers['set-cookie'].map(cookie => String(cookie).split(';', 1)[0]).filter(Boolean).join('; ')
        }
        return { csrfToken, cookies }
      } catch (error) {
        throw new Error(`Gagal ambil halaman awal: ${error.message}`)
      }
    }
    async function postDownloadRequest(downloadUrl, userUrl, csrfToken, cookies) {
      try {
        const axios = require('axios')
        const headers = {
          'User-Agent': 'Mozilla/5.0 (Linux; Android 10; RMX2185 Build/QP1A.190711.020) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/136.0.7103.60 Mobile Safari/537.36',
          'Referer': 'https://on4t.com/online-video-downloader',
          'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
          'Accept': '*/*',
          'X-Requested-With': 'XMLHttpRequest',
          'Cookie': cookies
        }
        const postData = new URLSearchParams()
        postData.append('_token', csrfToken)
        postData.append('link[]', userUrl)
        const response = await axios.post(downloadUrl, postData.toString(), { headers, timeout: 20000, maxContentLength: 5 * 1024 * 1024 })
        if (response.data?.result?.length) {
          const results = response.data.result.map(item => ({
            title: String(item?.title || 'Downloader Media').replace(/[\r\n\t]+/g, ' ').trim().slice(0, 140),
            thumb: item?.image || '',
            url: String(item?.video_file_url || item?.videoimg_file_url || '').trim()
          })).filter(item => /^https?:\/\//i.test(item.url));
          if (results.length) return results;
        }
        throw new Error('Respons provider tidak berisi tautan media yang valid.');
      } catch (error) {
        throw new Error(`Gagal proses permintaan download: ${error.message}`)
      }
    }
    async function sendMediaAutoType(url, title) {
      try {
        const axios = require('axios')
        const { fromBuffer } = require('file-type')   
        const res = await axios.get(url, { responseType: 'arraybuffer', timeout: 45000, maxContentLength: 64 * 1024 * 1024 })
        const buff = Buffer.from(res.data)
        const fileInfo = await fromBuffer(buff)
        if (!fileInfo) throw new Error(`Tipe file tidak dikenali: ${title}`)
        let mime = fileInfo.mime
        let ext = fileInfo.ext
        if (mime.startsWith('video/')) {
          await conn.sendMessage(m.chat, { video: buff, caption: title }, { quoted: m })
        } else if (mime.startsWith('audio/')) {
          await conn.sendMessage(m.chat, { audio: buff, mimetype: mime }, { quoted: m })
        } else if (mime.startsWith('image/')) {
          await conn.sendMessage(m.chat, { image: buff, caption: title }, { quoted: m })
        } else {
          await conn.sendMessage(m.chat, {
            document: buff,
            fileName: `${title}.${ext}`,
            mimetype: mime
          }, { quoted: m })
        }
        return true;
      } catch (err) {
        console.warn('[UNIVERSAL DOWNLOADER SEND ERROR]', err?.message || err)
        return false;
      }
    }
    const initialUrl = 'https://on4t.com/online-video-downloader'
    const downloadUrl = 'https://on4t.com/all-video-download'
    const { csrfToken, cookies } = await fetchInitialPage(initialUrl)
    const results = await postDownloadRequest(downloadUrl, scraprInputUrl, csrfToken, cookies)
    let sentCount = 0;
    for (const result of results) {
      if (await sendMediaAutoType(result.url, result.title)) sentCount++;
    }
    if (!sentCount) throw new Error('Provider menemukan respons, tetapi tidak ada media yang berhasil dikirim.');
    await conn.sendMessage(m.chat, { react: { text: '✅', key: m.key } })
  } catch (err) {
    await conn.sendMessage(m.chat, { react: { text: '❌', key: m.key } }) 
    await replyV1(err.message)
  }
break;
