  if (!text) return replyV1("Kirim link Telegram sticker pack.");
async function sendTelegramPackAsStickers(conn, from, m, stickerUrl) {
  try {
    // --- FETCH API ---
    const apiURL = `https://api.nekolabs.web.id/downloader/telegram-sticker?url=${encodeURIComponent(stickerUrl)}`;
    const res = await axios.get(apiURL);
    const data = res.data;

    // --- VALIDASI ---
    if (!data.success || !data.result || !data.result.stickers) {
      return conn.sendMessage(from, { text: "Gagal mengambil stiker dari API." }, { quoted: qtoko });
    }

    const packName = data.result.title || data.result.name;
    const stickerList = data.result.stickers;

    // --- INFO MULAI ---
    await conn.sendMessage(from, { text: `Mengirim ${stickerList.length} stiker...\nPack: *${packName}*` }, { quoted: qtoko });

    // --- LOOP KIRIM STIKER ---
    for (const sticker of stickerList) {
      try {
        await conn.sendImageAsSticker(
          from,
          sticker.image_url,
          m,
          {
            packname: packName,
            author: "Telegram Sticker Downloader"
          }
        );

        await delay(400); // aman biar no flood
      } catch (sendErr) {
        console.error("Error kirim stiker:", sendErr);
      }
    }

    // --- INFO SELESAI ---
    await conn.sendMessage(from, { text: `Selesai!\nTotal terkirim: ${stickerList.length} stiker.` }, { quoted: qtoko });

  } catch (err) {
    console.error("ERROR UTAMA:", err);
    return conn.sendMessage(from, { text: "Terjadi error saat mengambil pack." }, { quoted: qtoko });
  }
}

// === DELAY FUNCTION ===
function delay(ms) {
  return new Promise(res => setTimeout(res, ms));
}
  await sendTelegramPackAsStickers(conn, from, m, text);
