async function openai(messages, logic) {
    const apiKey = String(global.groqApiKey || '').trim()
    if (!apiKey) throw new Error('API AI belum dikonfigurasi.')

    const controller = new AbortController()
    const timeout = setTimeout(() => controller.abort(), 30000)

    try {
        const response = await fetch('https://api.groq.com/openai/v1/chat/completions', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            },
            signal: controller.signal,
            body: JSON.stringify({
                model: 'openai/gpt-oss-120b',
                messages: [
                    { role: 'system', content: logic },
                    ...messages
                ],
                temperature: 0.7
            })
        })

        const data = await response.json().catch(() => ({}))
        if (!response.ok) {
            const status = Number(response.status || 0)
            if (status === 429) throw new Error('AI sedang sibuk, coba lagi sebentar.')
            throw new Error(data?.error?.message || `AI HTTP ${status || 'error'}`)
        }

        const result = data?.choices?.[0]?.message?.content
        if (!result) throw new Error('AI tidak mengirim jawaban.')
        return result.trim()
    } finally {
        clearTimeout(timeout)
    }
}

