default:
if (isCmd && command && !['>', '=>', '$'].includes(command[0])) {
    try {
        if (!global.__xeryuuKnownCommands) {
            const source = fs.readFileSync(__filename, 'utf8')
            const names = [...source.matchAll(/case\s+['"]([a-z0-9_-]+)['"]\s*:/gi)].map(match => String(match[1]).toLowerCase())
            global.__xeryuuKnownCommands = [...new Set(names)].filter(name => name && name.length <= 40)
        }
        const distance = (a, b) => {
            a = String(a); b = String(b)
            const row = Array.from({ length: b.length + 1 }, (_, i) => i)
            for (let i = 1; i <= a.length; i++) {
                let prev = row[0]; row[0] = i
                for (let j = 1; j <= b.length; j++) {
                    const old = row[j]
                    row[j] = Math.min(row[j] + 1, row[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1))
                    prev = old
                }
            }
            return row[b.length]
        }
        const target = command.toLowerCase().replace(/[^a-z0-9_-]/g, '')
        const candidates = global.__xeryuuKnownCommands
            .filter(name => name !== target && Math.abs(name.length - target.length) <= 3)
            .map(name => ({ name, score: distance(target, name) }))
            .sort((a, b) => a.score - b.score || a.name.length - b.name.length)
        const best = candidates[0]
        const allowedDistance = target.length <= 4 ? 1 : target.length <= 8 ? 2 : 3
        const chosenPrefix = commandPrefix || prefix
        if (best && best.score <= allowedDistance) {
            // Skor rekomendasi dibuat mudah dibaca: satu kesalahan ketik = 90%.
            const similarity = Math.max(0, 100 - best.score * 10)
            return conn.sendMessage(m.chat, {
                text: `${command} tidak ditemukan, mungkin yang kamu maksud adalah\n${chosenPrefix}${best.name}\n\nkemiripan : ${similarity}%\n> xnalznotdev`
            }, { quoted: m })
        }
        return conn.sendMessage(m.chat, {
            text: `${command} tidak ditemukan. Ketik ${chosenPrefix}menu untuk melihat daftar fitur yang tersedia.\n> xnalznotdev`
        }, { quoted: m })
    } catch (suggestError) {
        console.error('[UNKNOWN COMMAND SUGGESTION]', suggestError?.message || suggestError)
    }
}
